(295496,32833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eller serbest daha az ..., özgürlük bir kazaya değmez.'::text,'sürmelisin'::text,'süreceksin'::text,'sürmelisin'::text,'Kanka, eller serbest daha az sürmelisin, özgürlük bir kazaya değmez.'::text),
(295497,32833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, kevesebbet ... kéz nélkül bringáznod, a szabadság nem ér meg egy esést.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tesó, kevesebbet kellene kéz nélkül bringáznod, a szabadság nem ér meg egy esést.'::text),
(295995,32889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... ein Held, dein Kühlschrank ist so voll.'::text,'bist'::text,'ist'::text,'bin'::text,'Ehrlich, du bist ein Held, dein Kühlschrank ist so voll.'::text),
(295999,32889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... герой, твій холодильник такий повний.'::text,'є'::text,'є'::text,'є'::text,'Чесно, ти є герой, твій холодильник такий повний.'::text),
(295998,32889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tú ... un héroe, tu nevera está tan llena.'::text,'eres'::text,'es'::text,'soy'::text,'En serio, tú eres un héroe, tu nevera está tan llena.'::text),
(295997,32889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... un héros, ton frigo est trop plein.'::text,'es'::text,'est'::text,'suis'::text,'Franchement, tu es un héros, ton frigo est trop plein.'::text),
(296000,32889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bir kahraman ..., buzdolabın tıka basa dolu.'::text,''::text,NULL::text,NULL::text,'Açıkçası sen bir kahraman, buzdolabın tıka basa dolu.'::text),
(296001,32889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te egy hős ..., annyira tele van a hűtőd.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Őszintén, te egy hős vagy, annyira tele van a hűtőd.'::text),
(296013,32891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kühlschrank ist voll, also ... er kein weiteres Essen hineintun.'::text,'kann'::text,'kann'::text,'ist'::text,'Der Kühlschrank ist voll, also kann er kein weiteres Essen hineintun.'::text),
(296017,32891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Холодильник повний, тож він ... покласти більше їжі.'::text,'не може'::text,'не може'::text,'не є'::text,'Холодильник повний, тож він не може покласти більше їжі.'::text),
(296016,32891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nevera está llena, así que él ... meter más comida.'::text,'no puede'::text,'no puede'::text,'no está'::text,'La nevera está llena, así que él no puede meter más comida.'::text),
(296015,32891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frigo est plein, donc il ... mettre plus de nourriture.'::text,'ne peut pas'::text,'ne peut pas'::text,'n''est pas'::text,'Le frigo est plein, donc il ne peut pas mettre plus de nourriture.'::text),
(296018,32891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabı dolu, bu yüzden daha fazla yiyecek ...'::text,'koyamaz'::text,'koyamaz'::text,'değil'::text,'Buzdolabı dolu, bu yüzden daha fazla yiyecek koyamaz.'::text),
(296019,32891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tele van a hűtő, ezért ... több ételt betenni.'::text,'nem tud'::text,'nem tud'::text,'nincs'::text,'Tele van a hűtő, ezért nem tud több ételt betenni.'::text),
(296022,32892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist der Kühlschrank jetzt voll? Weil er ihn mit Essen gefüllt hat.'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum ist der Kühlschrank jetzt voll? Weil er ihn mit Essen gefüllt hat.'::text),
(296026,32892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... холодильник зараз повний? Бо він наповнив його їжею.'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому холодильник зараз повний? Бо він наповнив його їжею.'::text),
(296025,32892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está llena la nevera ahora? Porque él la llenó de comida.'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué está llena la nevera ahora? Porque él la llenó de comida.'::text),
(296024,32892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le frigo est-il plein maintenant ? Parce qu''il l''a rempli de nourriture.'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi le frigo est-il plein maintenant ? Parce qu''il l''a rempli de nourriture.'::text),
(296027,32892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabı şimdi ... dolu? Çünkü onu yiyecekle doldurdu.'::text,'neden'::text,'kim'::text,'nerede'::text,'Buzdolabı şimdi neden dolu? Çünkü onu yiyecekle doldurdu.'::text),
(296028,32892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van most tele a hűtő? Mert megtöltötte étellel.'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért van most tele a hűtő? Mert megtöltötte étellel.'::text),
(296031,32893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel erreicht: Hände ... den leeren Kühlschrank in 5 Minuten voll.'::text,'bekamen'::text,'bekommen'::text,'bekamen'::text,'Ziel erreicht: Hände bekamen den leeren Kühlschrank in 5 Minuten voll.'::text),
(296035,32893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль досягнуто: руки ... порожній холодильник за 5 хвилин.'::text,'заповнили'::text,'заповнюють'::text,'заповнили'::text,'Ціль досягнуто: руки заповнили порожній холодильник за 5 хвилин.'::text),
(296034,32893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo cumplido: unas manos ... la nevera vacía en 5 minutos.'::text,'llenaron'::text,'llenan'::text,'llenaron'::text,'Objetivo cumplido: unas manos llenaron la nevera vacía en 5 minutos.'::text),
(296033,32893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif atteint : des mains ... le frigo vide en 5 minutes.'::text,'ont rempli'::text,'remplissent'::text,'ont rempli'::text,'Objectif atteint : des mains ont rempli le frigo vide en 5 minutes.'::text),
(296036,32893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefe ulaşıldı: eller boş buzdolabını 5 dakikada ...'::text,'doldurdu'::text,'doldurur'::text,'doldurdu'::text,'Hedefe ulaşıldı: eller boş buzdolabını 5 dakikada doldurdu.'::text),
(296037,32893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél teljesítve: kezek 5 perc alatt ... az üres hűtőt.'::text,'megtöltötték'::text,'megtöltik'::text,'megtöltötték'::text,'Cél teljesítve: kezek 5 perc alatt megtöltötték az üres hűtőt.'::text),
(296040,32894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kühlschrank hat jetzt mehr Essen, also ist er ... als vorher.'::text,'voller'::text,'voller'::text,'am vollsten'::text,'Der Kühlschrank hat jetzt mehr Essen, also ist er voller als vorher.'::text),
(296044,32894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У холодильнику тепер більше їжі, тож він ..., ніж раніше.'::text,'повніший'::text,'повніший'::text,'найповніший'::text,'У холодильнику тепер більше їжі, тож він повніший, ніж раніше.'::text),
(296043,32894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nevera tiene más comida ahora, así que está ... que antes.'::text,'más llena'::text,'más llena'::text,'la más llena'::text,'La nevera tiene más comida ahora, así que está más llena que antes.'::text),
(296042,32894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frigo a plus de nourriture maintenant, donc il est ... qu''avant.'::text,'plus plein'::text,'plus plein'::text,'le plus plein'::text,'Le frigo a plus de nourriture maintenant, donc il est plus plein qu''avant.'::text),
(296045,32894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabında artık daha çok yiyecek var, bu yüzden öncekinden ...'::text,'daha dolu'::text,'daha dolu'::text,'en dolu'::text,'Buzdolabında artık daha çok yiyecek var, bu yüzden öncekinden daha dolu.'::text),
(296046,32894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hűtőben most több étel van, ezért ..., mint korábban.'::text,'teltebb'::text,'teltebb'::text,'legteltebb'::text,'A hűtőben most több étel van, ezért teltebb, mint korábban.'::text),
(296058,32896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Kühlschrank war leer, ... jetzt ist er voll. Ehrlich, stark.'::text,'aber'::text,'weil'::text,'also'::text,'Dein Kühlschrank war leer, aber jetzt ist er voll. Ehrlich, stark.'::text),
(296062,32896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твій холодильник був порожній, ... тепер він повний. Чесно, красиво.'::text,'але'::text,'бо'::text,'тому'::text,'Твій холодильник був порожній, але тепер він повний. Чесно, красиво.'::text),
(296061,32896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu nevera estaba vacía, ... ahora está llena. En serio, qué arte.'::text,'pero'::text,'porque'::text,'así que'::text,'Tu nevera estaba vacía, pero ahora está llena. En serio, qué arte.'::text),
(296060,32896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton frigo était vide, ... maintenant il est plein. Franchement, la classe.'::text,'mais'::text,'parce que'::text,'donc'::text,'Ton frigo était vide, mais maintenant il est plein. Franchement, la classe.'::text),
(296063,32896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdolabın boştu ... şimdi dolu. Cidden, çok şık.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Buzdolabın boştu ama şimdi dolu. Cidden, çok şık.'::text),
(296064,32896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üres volt a hűtőd, ... most tele van. Őszintén, ügyes.'::text,'de'::text,'mert'::text,'ezért'::text,'Üres volt a hűtőd, de most tele van. Őszintén, ügyes.'::text),
(315363,35041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Freunde ... sich eine Eistüte teilen.'::text,'können'::text,'können'::text,'sind'::text,'Zwei Freunde können sich eine Eistüte teilen.'::text),
(315367,35041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє друзів ... розділити один ріжок морозива.'::text,'можуть'::text,'можуть'::text,'є'::text,'Двоє друзів можуть розділити один ріжок морозива.'::text),
(315366,35041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos amigos ... compartir un cucurucho de helado.'::text,'pueden'::text,'pueden'::text,'están'::text,'Dos amigos pueden compartir un cucurucho de helado.'::text),
(315365,35041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux amis ... partager un cornet de glace.'::text,'peuvent'::text,'peuvent'::text,'sont'::text,'Deux amis peuvent partager un cornet de glace.'::text),
(315368,35041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki arkadaş bir külah dondurmayı ...'::text,'paylaşabilir'::text,'paylaşabilir'::text,NULL::text,'İki arkadaş bir külah dondurmayı paylaşabilir.'::text),
(315369,35041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két barát ... egy tölcsér fagyin.'::text,'osztozhat'::text,'osztozhat'::text,'van'::text,'Két barát osztozhat egy tölcsér fagyin.'::text),
(315372,35042,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... teilen die sich? Ein Eis.'::text,'was'::text,'wer'::text,'wo'::text,'Bro, was teilen die sich? Ein Eis.'::text),
(315376,35042,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... вони ділитимуть? Одне морозиво.'::text,'що'::text,'хто'::text,'де'::text,'Бро, що вони ділитимуть? Одне морозиво.'::text),
(315375,35042,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... van a compartir? Un helado.'::text,'qué'::text,'quién'::text,'dónde'::text,'Tío, ¿qué van a compartir? Un helado.'::text),
(315374,35042,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ils vont partager ... ? Une glace.'::text,'quoi'::text,'qui'::text,'où'::text,'Frère, ils vont partager quoi ? Une glace.'::text),
(315377,35042,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... paylaşacaklar? Tek bir dondurma.'::text,'neyi'::text,'kimi'::text,'nerede'::text,'Kanka, neyi paylaşacaklar? Tek bir dondurma.'::text),
(315378,35042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fognak megosztani? Egy fagyit.'::text,'mit'::text,'kit'::text,'hol'::text,'Tesó, mit fognak megosztani? Egy fagyit.'::text),
(315381,35043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, gestern ... sie sich ein Eis, irgendwie Kult.'::text,'teilten'::text,'teilt'::text,'teilen'::text,'Nee, gestern teilten sie sich ein Eis, irgendwie Kult.'::text),
(315385,35043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, вчора вони ... одне морозиво, це легендарно.'::text,'розділили'::text,'ділить'::text,'ділять'::text,'Не, вчора вони розділили одне морозиво, це легендарно.'::text),
(315384,35043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, ayer ... un helado, bastante icónico.'::text,'compartieron'::text,'comparte'::text,'comparten'::text,'Qué va, ayer compartieron un helado, bastante icónico.'::text),
(315383,35043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, hier ils ... une glace, un peu iconique.'::text,'ont partagé'::text,'partage'::text,'partagent'::text,'Non, hier ils ont partagé une glace, un peu iconique.'::text),
(315386,35043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, dün bir dondurmayı ..., resmen efsane.'::text,'paylaştılar'::text,'paylaşır'::text,'paylaşırlar'::text,'Yok, dün bir dondurmayı paylaştılar, resmen efsane.'::text),
(315387,35043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tegnap egy fagyin ..., elég ikonikus.'::text,'osztoztak'::text,'osztozik'::text,'osztoznak'::text,'Nem, tegnap egy fagyin osztoztak, elég ikonikus.'::text),
(315390,35044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budgetkürzung: Gestern ... sich das Team 1 Eistüte.'::text,'teilte'::text,'teilen'::text,NULL::text,'Budgetkürzung: Gestern teilte sich das Team 1 Eistüte.'::text),
(315394,35044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скорочення бюджету: учора команда ... 1 ріжок морозива.'::text,'розділила'::text,'ділити'::text,NULL::text,'Скорочення бюджету: учора команда розділила 1 ріжок морозива.'::text),
(315393,35044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Recorte de presupuesto: ayer el equipo ... 1 cucurucho de helado.'::text,'compartió'::text,'compartir'::text,NULL::text,'Recorte de presupuesto: ayer el equipo compartió 1 cucurucho de helado.'::text),
(315392,35044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Coupe budgétaire : hier, l''équipe ... 1 cornet de glace.'::text,'a partagé'::text,'partager'::text,NULL::text,'Coupe budgétaire : hier, l''équipe a partagé 1 cornet de glace.'::text),
(315395,35044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe kesintisi: dün ekip 1 külah dondurmayı ...'::text,'paylaştı'::text,'paylaşmak'::text,NULL::text,'Bütçe kesintisi: dün ekip 1 külah dondurmayı paylaştı.'::text),
(315396,35044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségcsökkentés: tegnap a csapat 1 tölcsér fagyin ...'::text,'osztozott'::text,'osztozni'::text,NULL::text,'Költségcsökkentés: tegnap a csapat 1 tölcsér fagyin osztozott.'::text),
(315399,35045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich jetzt eine Tüte, weil es nur eine Tüte gibt.'::text,'teilen'::text,'teilen'::text,'teilen'::text,'Sie teilen sich jetzt eine Tüte, weil es nur eine Tüte gibt.'::text),
(315403,35045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони зараз ... один ріжок, бо є лише один ріжок.'::text,'ділять'::text,'ділять'::text,'ділять'::text,'Вони зараз ділять один ріжок, бо є лише один ріжок.'::text),
(315402,35045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... un cucurucho porque solo hay un cucurucho.'::text,'están compartiendo'::text,'comparten'::text,'están compartiendo'::text,'Ahora están compartiendo un cucurucho porque solo hay un cucurucho.'::text),
(315401,35045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... un cornet maintenant parce qu''il n''y a qu''un seul cornet.'::text,'sont en train de partager'::text,'partagent'::text,'sont en train de partager'::text,'Ils sont en train de partager un cornet maintenant parce qu''il n''y a qu''un seul cornet.'::text),
(315404,35045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi tek bir külahı ... çünkü sadece bir külah var.'::text,'paylaşıyorlar'::text,'paylaşırlar'::text,'paylaşıyorlar'::text,'Şimdi tek bir külahı paylaşıyorlar çünkü sadece bir külah var.'::text),
(315405,35045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most egy tölcséren ..., mert csak egy tölcsér van.'::text,'osztoznak'::text,'osztoznak'::text,'osztoznak'::text,'Most egy tölcséren osztoznak, mert csak egy tölcsér van.'::text),
(315417,35047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt dieses Eis, ... er teilt es! Wahre Freundschaft für immer!'::text,'aber'::text,'also'::text,'weil'::text,'Er liebt dieses Eis, aber er teilt es! Wahre Freundschaft für immer!'::text),
(315421,35047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обожнює те морозиво, ... ділиться ним! Справжня дружба назавжди!'::text,'але'::text,'тому'::text,'бо'::text,'Він обожнює те морозиво, але ділиться ним! Справжня дружба назавжди!'::text),
(315420,35047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Le encanta ese helado, ... lo comparte! ¡Amistad verdadera para siempre!'::text,'pero'::text,'así que'::text,'porque'::text,'¡Le encanta ese helado, pero lo comparte! ¡Amistad verdadera para siempre!'::text),
(315419,35047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore cette glace, ... il la partage ! Une vraie amitié pour toujours !'::text,'mais'::text,'donc'::text,'parce que'::text,'Il adore cette glace, mais il la partage ! Une vraie amitié pour toujours !'::text),
(315422,35047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dondurmaya bayılıyor ... onu paylaşıyor! Sonsuza dek gerçek dostluk!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'O dondurmaya bayılıyor ama onu paylaşıyor! Sonsuza dek gerçek dostluk!'::text),
(315423,35047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádja azt a fagyit, ... megosztja! Igaz barátság örökre!'::text,'de'::text,'ezért'::text,'mert'::text,'Imádja azt a fagyit, de megosztja! Igaz barátság örökre!'::text),
(317973,35331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... den besten Platz auf dem Sofa. So cool.'::text,'hast'::text,'hat'::text,'hast'::text,'Du hast den besten Platz auf dem Sofa. So cool.'::text),
(317977,35331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... найкраще місце на дивані. Так круто.'::text,'маєш'::text,'має'::text,'маєш'::text,'Ти маєш найкраще місце на дивані. Так круто.'::text),
(317976,35331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el mejor sitio del sofá. Qué guay.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Tú tienes el mejor sitio del sofá. Qué guay.'::text),
(317975,35331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la meilleure place sur le canapé. Trop cool.'::text,'as'::text,'a'::text,'as'::text,'Tu as la meilleure place sur le canapé. Trop cool.'::text),
(317978,35331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanepedeki en iyi yer sende ...! Çok havalı.'::text,'var'::text,'var'::text,'var'::text,'Kanepedeki en iyi yer sende var! Çok havalı.'::text),
(317979,35331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked ... a legjobb hely a kanapén. Nagyon menő.'::text,'van'::text,'van'::text,'van'::text,'Neked van a legjobb hely a kanapén. Nagyon menő.'::text),
(317982,35332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr zwei habt zwei ... auf diesem Sofa. Respekt.'::text,'Controller'::text,'Controller'::text,'Controller'::text,'Ihr zwei habt zwei Controller auf diesem Sofa. Respekt.'::text),
(317986,35332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У вас двох два ... на тому дивані. Респект.'::text,'контролери'::text,'контролер'::text,'контролери'::text,'У вас двох два контролери на тому дивані. Респект.'::text),
(317985,35332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vosotros dos tenéis dos ... en ese sofá. Respeto.'::text,'mandos'::text,'mando'::text,'mandos'::text,'Vosotros dos tenéis dos mandos en ese sofá. Respeto.'::text),
(317984,35332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vous deux, vous avez deux ... sur ce canapé. Respect.'::text,'manettes'::text,'manette'::text,'manettes'::text,'Vous deux, vous avez deux manettes sur ce canapé. Respect.'::text),
(317987,35332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kanepede siz ikinizde iki ... var. Saygılar.'::text,'kumanda'::text,'kumanda'::text,'kumandalar'::text,'O kanepede siz ikinizde iki kumanda var. Saygılar.'::text),
(317988,35332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... van nálatok azon a kanapén. Respekt.'::text,'kontroller'::text,'kontroller'::text,'kontroller'::text,'Két kontroller van nálatok azon a kanapén. Respekt.'::text),
(318000,35334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Schüssel Chips steht auf dem Sofa.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Schüssel Chips steht auf dem Sofa.'::text),
(318004,35334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... миска чипсів стоїть на дивані.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця миска чипсів стоїть на дивані.'::text),
(318003,35334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cuenco de patatas fritas está en el sofá.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este cuenco de patatas fritas está en el sofá.'::text),
(318002,35334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bol de chips est sur le canapé.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce bol de chips est sur le canapé.'::text),
(318005,35334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kase cips kanepenin üstünde.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu kase cips kanepenin üstünde.'::text),
(318006,35334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a tál chips a kanapén van.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a tál chips a kanapén van.'::text),
(318009,35335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie springt auf das Sofa und hebt ... Faust.'::text,'ihre'::text,'seine'::text,'seine'::text,'Sie springt auf das Sofa und hebt ihre Faust.'::text),
(318013,35335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона стрибає на диван і піднімає ... кулак.'::text,'свій'::text,'свій'::text,'свій'::text,'Вона стрибає на диван і піднімає свій кулак.'::text),
(318012,35335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salta al sofá y levanta ... puño.'::text,'su'::text,'su'::text,'su'::text,'Salta al sofá y levanta su puño.'::text),
(318011,35335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle saute sur le canapé et lève ... poing.'::text,'son'::text,'son'::text,'son'::text,'Elle saute sur le canapé et lève son poing.'::text),
(318014,35335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanepeye zıplıyor ve ... yumruğunu kaldırıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kanepeye zıplıyor ve onun yumruğunu kaldırıyor.'::text),
(318015,35335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felugrik a kanapéra, és felemeli az ...'::text,'öklét'::text,'öklét'::text,'öklét'::text,'Felugrik a kanapéra, és felemeli az öklét.'::text),
(318018,35336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schüssel Chips steht ... dem Sofa zwischen ihnen.'::text,'auf'::text,'in'::text,'an'::text,'Die Schüssel Chips steht auf dem Sofa zwischen ihnen.'::text),
(318022,35336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Миска чипсів стоїть ... дивані між ними.'::text,'на'::text,'у'::text,'біля'::text,'Миска чипсів стоїть на дивані між ними.'::text),
(318021,35336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cuenco de patatas fritas está ... el sofá entre ellos.'::text,'en'::text,'en'::text,'a'::text,'El cuenco de patatas fritas está en el sofá entre ellos.'::text),
(318020,35336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bol de chips est ... le canapé entre eux.'::text,'sur'::text,'dans'::text,'à'::text,'Le bol de chips est sur le canapé entre eux.'::text),
(318023,35336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cips kasesi ikisinin arasında, kanepenin ...'::text,'üstünde'::text,'içinde'::text,NULL::text,'Cips kasesi ikisinin arasında, kanepenin üstünde.'::text),
(318024,35336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A chipses tál a ... van kettejük között.'::text,'kanapén'::text,'kanapéban'::text,'kanapénál'::text,'A chipses tál a kanapén van kettejük között.'::text),
(318027,35337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Freunde sitzen mit ... Controllern auf dem Sofa.'::text,'zwei'::text,'zweiten'::text,'Zweien'::text,'Zwei Freunde sitzen mit zwei Controllern auf dem Sofa.'::text),
(318031,35337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє друзів сидять на дивані з ... контролерами.'::text,'двома'::text,'другими'::text,'двійками'::text,'Двоє друзів сидять на дивані з двома контролерами.'::text),
(318030,35337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos amigos se sientan en el sofá con ... mandos.'::text,'dos'::text,'segundos'::text,'dos'::text,'Dos amigos se sientan en el sofá con dos mandos.'::text),
(318029,35337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux amis sont assis sur le canapé avec ... manettes.'::text,'deux'::text,'deuxièmes'::text,'deux'::text,'Deux amis sont assis sur le canapé avec deux manettes.'::text),
(318032,35337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki arkadaş ... kumandayla kanepede oturuyor.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'İki arkadaş iki kumandayla kanepede oturuyor.'::text),
(318033,35337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két barát ... kontrollerrel ül a kanapén.'::text,'két'::text,'második'::text,'kettesek'::text,'Két barát két kontrollerrel ül a kanapén.'::text),
(296418,32936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... jeden Sommer, das ist ihr ganzer Vibe.'::text,'gärtnert'::text,'gärtnerte'::text,NULL::text,'Bro, sie gärtnert jeden Sommer, das ist ihr ganzer Vibe.'::text),
(296422,32936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... кожного літа, це весь її вайб.'::text,'порається в саду'::text,'поралася в саду'::text,NULL::text,'Бро, вона порається в саду кожного літа, це весь її вайб.'::text),
(296421,32936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... cada verano, es todo su rollo.'::text,'trabaja en el jardín'::text,'trabajó en el jardín'::text,NULL::text,'Tío, ella trabaja en el jardín cada verano, es todo su rollo.'::text),
(296420,32936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... chaque été, c''est toute sa vibe.'::text,'jardine'::text,'a jardiné'::text,NULL::text,'Frère, elle jardine chaque été, c''est toute sa vibe.'::text),
(296423,32936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her yaz ..., onun tüm olayı bu.'::text,'bahçeyle uğraşır'::text,'bahçeyle uğraştı'::text,NULL::text,'Kanka, her yaz bahçeyle uğraşır, onun tüm olayı bu.'::text),
(296424,32936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, minden nyáron ..., ez az ő stílusa.'::text,'kertészkedik'::text,'kertészkedett'::text,NULL::text,'Tesó, minden nyáron kertészkedik, ez az ő stílusa.'::text),
(296427,32937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, Oma ... gerade in der Sonne, irgendwie Kult.'::text,'gärtnert'::text,'gärtnert'::text,'gärtnert'::text,'Yo, Oma gärtnert gerade in der Sonne, irgendwie Kult.'::text),
(296431,32937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бабуся саме зараз ... на сонці, легендарно.'::text,'порається в саду'::text,'порається в саду'::text,'порається в саду'::text,'Йо, бабуся саме зараз порається в саду на сонці, легендарно.'::text),
(296430,32937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la abuela ... al sol ahora mismo, bastante icónico.'::text,'está trabajando en el jardín'::text,'trabaja en el jardín'::text,'está trabajando en el jardín'::text,'Tío, la abuela está trabajando en el jardín al sol ahora mismo, bastante icónico.'::text),
(296429,32937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, mamie ... au soleil en ce moment, un peu iconique.'::text,'est en train de jardiner'::text,'jardine'::text,'est en train de jardiner'::text,'Yo, mamie est en train de jardiner au soleil en ce moment, un peu iconique.'::text),
(296432,32937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, büyükanne şu an güneşte ..., resmen efsane.'::text,'bahçeyle uğraşıyor'::text,'bahçeyle uğraşır'::text,'bahçeyle uğraşıyor'::text,'Kanka, büyükanne şu an güneşte bahçeyle uğraşıyor, resmen efsane.'::text),
(296433,32937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a mama most épp a napon ..., elég ikonikus.'::text,'kertészkedik'::text,'kertészkedik'::text,'kertészkedik'::text,'Figyu, a mama most épp a napon kertészkedik, elég ikonikus.'::text),
(296436,32938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An den meisten Tagen liest sie, aber heute ... sie zwischen den Rosen.'::text,'gärtnert'::text,'gärtnert'::text,NULL::text,'An den meisten Tagen liest sie, aber heute gärtnert sie zwischen den Rosen.'::text),
(296440,32938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Більшість днів вона читає, але сьогодні ... серед троянд.'::text,'порається в саду'::text,'порається в саду'::text,NULL::text,'Більшість днів вона читає, але сьогодні порається в саду серед троянд.'::text),
(296439,32938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mayoría de los días lee, pero hoy ... entre las rosas.'::text,'está trabajando en el jardín'::text,'trabaja en el jardín'::text,NULL::text,'La mayoría de los días lee, pero hoy está trabajando en el jardín entre las rosas.'::text),
(296438,32938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plupart du temps elle lit, mais aujourd''hui elle ... parmi les roses.'::text,'est en train de jardiner'::text,'jardine'::text,NULL::text,'La plupart du temps elle lit, mais aujourd''hui elle est en train de jardiner parmi les roses.'::text),
(296441,32938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çoğu gün kitap okur ama bugün güllerin arasında ...'::text,'bahçeyle uğraşıyor'::text,'bahçeyle uğraşır'::text,NULL::text,'Çoğu gün kitap okur ama bugün güllerin arasında bahçeyle uğraşıyor.'::text),
(296442,32938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legtöbb napon olvas, de ma a rózsák között ...'::text,'kertészkedik'::text,'kertészkedik'::text,NULL::text,'A legtöbb napon olvas, de ma a rózsák között kertészkedik.'::text),
(296454,32940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schubkarre ist bereit! Sie ... den ganzen Tag gärtnern und nie aufhören! Absolut!'::text,'wird'::text,'wird'::text,'gärtnert'::text,'Die Schubkarre ist bereit! Sie wird den ganzen Tag gärtnern und nie aufhören! Absolut!'::text),
(296458,32940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тачка готова! Вона ... цілий день і ніколи не зупинятиметься! Абсолютно!'::text,'збирається поратися в саду'::text,'поратиметься в саду'::text,'порається в саду'::text,'Тачка готова! Вона збирається поратися в саду цілий день і ніколи не зупинятиметься! Абсолютно!'::text),
(296457,32940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La carretilla está lista! ¡Ella ... todo el día y nunca parará! ¡Totalmente!'::text,'va a trabajar en el jardín'::text,'trabajará en el jardín'::text,'trabaja en el jardín'::text,'¡La carretilla está lista! ¡Ella va a trabajar en el jardín todo el día y nunca parará! ¡Totalmente!'::text),
(296456,32940,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La brouette est prête ! Elle ... toute la journée et ne s''arrêtera jamais ! Absolument !'::text,'va jardiner'::text,'jardinera'::text,'jardine'::text,'La brouette est prête ! Elle va jardiner toute la journée et ne s''arrêtera jamais ! Absolument !'::text),
(296459,32940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arabası hazır! Bütün gün ... ve hiç durmayacak! Kesinlikle!'::text,'bahçeyle uğraşacak'::text,'bahçeyle uğraşacak'::text,'bahçeyle uğraşır'::text,'El arabası hazır! Bütün gün bahçeyle uğraşacak ve hiç durmayacak! Kesinlikle!'::text),
(296460,32940,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kész a talicska! Egész nap ... és soha nem áll le! Abszolút!'::text,'kertészkedni fog'::text,'kertészkedni fog'::text,'kertészkedik'::text,'Kész a talicska! Egész nap kertészkedni fog és soha nem áll le! Abszolút!'::text),
(296463,32941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Pause! „Ich ... für immer gärtnern!“, verspricht sie den Rosen.'::text,'werde'::text,'werde'::text,NULL::text,'Keine Pause! „Ich werde für immer gärtnern!“, verspricht sie den Rosen.'::text),
(296467,32941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодного відпочинку! «Я ... вічно!» — обіцяє вона трояндам.'::text,'поратимуся в саду'::text,'збираюся поратися в саду'::text,NULL::text,'Жодного відпочинку! «Я поратимуся в саду вічно!» — обіцяє вона трояндам.'::text),
(296466,32941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nada de descanso! «¡Yo ... para siempre!», promete a las rosas.'::text,'trabajaré en el jardín'::text,'voy a trabajar en el jardín'::text,NULL::text,'¡Nada de descanso! «¡Yo trabajaré en el jardín para siempre!», promete a las rosas.'::text),
(296465,32941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas de repos ! « Je ... pour toujours ! » promet-elle aux roses.'::text,'jardinerai'::text,'vais jardiner'::text,NULL::text,'Pas de repos ! « Je jardinerai pour toujours ! » promet-elle aux roses.'::text),
(296468,32941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinlenmek yok! “Sonsuza dek ...!” diye güllere söz veriyor.'::text,'bahçeyle uğraşacağım'::text,'bahçeyle uğraşacağım'::text,NULL::text,'Dinlenmek yok! “Sonsuza dek bahçeyle uğraşacağım!” diye güllere söz veriyor.'::text),
(296469,32941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs pihenő! „Örökké ...!” – ígéri a rózsáknak.'::text,'kertészkedni fogok'::text,'kertészkedni fogok'::text,NULL::text,'Nincs pihenő! „Örökké kertészkedni fogok!” – ígéri a rózsáknak.'::text),
(296472,32942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ihr Arzt hat gesagt, sie ... jeden Tag gärtnern.'::text,'muss'::text,'muss'::text,'sollte'::text,'Bestie, ihr Arzt hat gesagt, sie muss jeden Tag gärtnern.'::text),
(296476,32942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, її лікар сказав, що вона ... поратися в саду щодня.'::text,'має'::text,'мусить'::text,'мала б'::text,'Подруго, її лікар сказав, що вона має поратися в саду щодня.'::text),
(296475,32942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, su médico dijo que ella ... trabajar en el jardín todos los días.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Amiga, su médico dijo que ella tiene que trabajar en el jardín todos los días.'::text),
(296474,32942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, son médecin a dit qu''elle ... jardiner tous les jours.'::text,'doit'::text,'doit'::text,'devrait'::text,'Ma belle, son médecin a dit qu''elle doit jardiner tous les jours.'::text),
(296477,32942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, doktoru ona her gün bahçeyle ... dedi.'::text,'uğraşmak zorunda'::text,'uğraşmalı'::text,'uğraşmalı'::text,'Kızım, doktoru ona her gün bahçeyle uğraşmak zorunda dedi.'::text),
(296478,32942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az orvosa azt mondta, hogy minden nap kertészkednie ...'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, az orvosa azt mondta, hogy minden nap kertészkednie kell.'::text),
(296481,32943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, ich hab gehört, du ... mit ihr gärtnern, die Tomaten sind riesig.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Süße, ich hab gehört, du solltest mit ihr gärtnern, die Tomaten sind riesig.'::text),
(296485,32943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що ти ... поратися в саду з нею, помідори величезні.'::text,'мала б'::text,'будеш'::text,'мала б'::text,'Подруго, я чула, що ти мала б поратися в саду з нею, помідори величезні.'::text),
(296484,32943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que tú ... trabajar en el jardín con ella, los tomates son enormes.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tía, he oído que tú deberías trabajar en el jardín con ella, los tomates son enormes.'::text),
(296483,32943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que tu ... jardiner avec elle, les tomates sont énormes.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Ma belle, j''ai entendu dire que tu devrais jardiner avec elle, les tomates sont énormes.'::text),
(296486,32943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki onunla bahçeyle ..., domatesler kocaman.'::text,'uğraşmalısın'::text,'uğraşacaksın'::text,'uğraşmalısın'::text,'Kızım, duydum ki onunla bahçeyle uğraşmalısın, domatesler kocaman.'::text),
(296487,32943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy vele ... kertészkedned, hatalmasak a paradicsomok.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Csajszi, azt hallottam, hogy vele kellene kertészkedned, hatalmasak a paradicsomok.'::text),
(296499,32945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin ... ein Ziel von 20 runden Büschen.'::text,'hat'::text,'haben'::text,'hat'::text,'Die Gärtnerin hat ein Ziel von 20 runden Büschen.'::text),
(296503,32945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця ... ціль у 20 круглих кущів.'::text,'має'::text,'мати'::text,'має'::text,'Садівниця має ціль у 20 круглих кущів.'::text),
(296502,32945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinera ... un objetivo de 20 arbustos redondos.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La jardinera tiene un objetivo de 20 arbustos redondos.'::text),
(296501,32945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière ... un objectif de 20 buissons ronds.'::text,'a'::text,'ont'::text,'a'::text,'La jardinière a un objectif de 20 buissons ronds.'::text),
(296504,32945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvanın 20 yuvarlak çalılık bir hedefi ...'::text,'var'::text,'var'::text,'var'::text,'Bahçıvanın 20 yuvarlak çalılık bir hedefi var.'::text),
(296505,32945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertésznek 20 gömbbokorra szóló célja ...'::text,'van'::text,'van'::text,'van'::text,'A kertésznek 20 gömbbokorra szóló célja van.'::text),
(296508,32946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin schneidet die runden ... einen nach dem anderen.'::text,'Büsche'::text,'Busch'::text,'Büsche'::text,'Die Gärtnerin schneidet die runden Büsche einen nach dem anderen.'::text),
(296512,32946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця підстригає круглі ... один за одним.'::text,'кущі'::text,'кущ'::text,'кущі'::text,'Садівниця підстригає круглі кущі один за одним.'::text),
(296511,32946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinera poda los ... redondos uno a uno.'::text,'arbustos'::text,'arbusto'::text,'arbustos'::text,'La jardinera poda los arbustos redondos uno a uno.'::text),
(296510,32946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière taille les ... ronds un par un.'::text,'buissons'::text,'buisson'::text,'buissons'::text,'La jardinière taille les buissons ronds un par un.'::text),
(296513,32946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvan yuvarlak ... tek tek buduyor.'::text,'çalıları'::text,'çalıyı'::text,'çalıları'::text,'Bahçıvan yuvarlak çalıları tek tek buduyor.'::text),
(296514,32946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertész egyenként nyírja a gömbölyű ...'::text,'bokrokat'::text,'bokrot'::text,'bokrokat'::text,'A kertész egyenként nyírja a gömbölyű bokrokat.'::text),
(296517,32947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist ... Gärtnerin in einem großen Park.'::text,'eine'::text,'eine'::text,'die'::text,'Sie ist eine Gärtnerin in einem großen Park.'::text),
(296521,32947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... садівниця у великому парку.'::text,''::text,NULL::text,NULL::text,'Вона садівниця у великому парку.'::text),
(296520,32947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella es ... jardinera en un parque grande.'::text,'una'::text,'una'::text,'la'::text,'Ella es una jardinera en un parque grande.'::text),
(296519,32947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est ... jardinière dans un grand parc.'::text,'une'::text,'une'::text,'la'::text,'Elle est une jardinière dans un grand parc.'::text),
(296522,32947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O büyük bir parkta ... bahçıvan.'::text,'bir'::text,'bir'::text,NULL::text,'O büyük bir parkta bir bahçıvan.'::text),
(296523,32947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... kertész egy nagy parkban.'::text,'egy'::text,'egy'::text,'a'::text,'Ő egy kertész egy nagy parkban.'::text),
(296526,32948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin greift ... Büsche da drüben mit ihrer Schere an!'::text,'jene'::text,'jenen'::text,'diesen'::text,'Die Gärtnerin greift jene Büsche da drüben mit ihrer Schere an!'::text),
(296530,32948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця атакує ... кущі он там своїми ножицями!'::text,'ті'::text,'той'::text,'цей'::text,'Садівниця атакує ті кущі он там своїми ножицями!'::text),
(296529,32948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La jardinera ataca ... arbustos de allí con sus tijeras!'::text,'esos'::text,'ese'::text,'este'::text,'¡La jardinera ataca esos arbustos de allí con sus tijeras!'::text),
(296528,32948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière attaque ... buissons là-bas avec son sécateur !'::text,'ces'::text,'ce'::text,'ce'::text,'La jardinière attaque ces buissons là-bas avec son sécateur !'::text),
(296531,32948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvan makasıyla oradaki ... çalılara saldırıyor!'::text,'şu'::text,'şu'::text,'bu'::text,'Bahçıvan makasıyla oradaki şu çalılara saldırıyor!'::text),
(296532,32948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertész nekiesik ... a bokroknak ott hátul az ollójával!'::text,'azoknak'::text,'annak'::text,'ennek'::text,'A kertész nekiesik azoknak a bokroknak ott hátul az ollójával!'::text),
(296544,32950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin geht ... dem Kiesweg.'::text,'auf'::text,'an'::text,'unter'::text,'Die Gärtnerin geht auf dem Kiesweg.'::text),
(296548,32950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця йде ... гравійній доріжці.'::text,'по'::text,'біля'::text,'під'::text,'Садівниця йде по гравійній доріжці.'::text),
(296547,32950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinera camina ... el camino de grava.'::text,'por'::text,'a'::text,'debajo de'::text,'La jardinera camina por el camino de grava.'::text),
(296546,32950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière marche ... l''allée de gravier.'::text,'sur'::text,'à'::text,'sous'::text,'La jardinière marche sur l''allée de gravier.'::text),
(296549,32950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvan çakıl yolun ... yürüyor.'::text,'üstünde'::text,NULL::text,'altında'::text,'Bahçıvan çakıl yolun üstünde yürüyor.'::text),
(296550,32950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertész a kavicsos ... sétál.'::text,'úton'::text,'útnál'::text,'út alatt'::text,'A kertész a kavicsos úton sétál.'::text),
(296553,32951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Gärtnerin hat ... Schere, Bro.'::text,'eine'::text,'erste'::text,'einmal'::text,'Yo, die Gärtnerin hat eine Schere, Bro.'::text),
(296557,32951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, у садівниці ... ножиці, бро.'::text,'одні'::text,'перші'::text,'один раз'::text,'Йо, у садівниці одні ножиці, бро.'::text),
(296556,32951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la jardinera tiene ... par de tijeras, tío.'::text,'un'::text,'primer'::text,'una vez'::text,'Oye, la jardinera tiene un par de tijeras, tío.'::text),
(296555,32951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la jardinière a ... paire de cisailles, frère.'::text,'une'::text,'première'::text,'une fois'::text,'Yo, la jardinière a une paire de cisailles, frère.'::text),
(296558,32951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, bahçıvanın ... makası var, kanka.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Hey, bahçıvanın bir makası var, kanka.'::text),
(296559,32951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a kertésznek ... ollója van, tesó.'::text,'egy'::text,'első'::text,'egyszer'::text,'Figyu, a kertésznek egy ollója van, tesó.'::text),
(294222,32692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Aussichtspunkt am Canyon ... einen Holzzaun entlang der Kante.'::text,'hat'::text,'haben'::text,'ist'::text,'Der Aussichtspunkt am Canyon hat einen Holzzaun entlang der Kante.'::text),
(294226,32692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оглядовий майданчик над каньйоном ... дерев''яний паркан уздовж краю.'::text,'має'::text,'мати'::text,'є'::text,'Оглядовий майданчик над каньйоном має дерев''яний паркан уздовж краю.'::text),
(294225,32692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mirador del cañón ... una valla de madera a lo largo del borde.'::text,'tiene'::text,'tienen'::text,'está'::text,'El mirador del cañón tiene una valla de madera a lo largo del borde.'::text),
(294224,32692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le belvédère du canyon ... une clôture en bois le long du bord.'::text,'a'::text,'ont'::text,'est'::text,'Le belvédère du canyon a une clôture en bois le long du bord.'::text),
(294227,32692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanyon seyir noktasının kenar boyunca ahşap bir çiti ...'::text,'var'::text,'var'::text,NULL::text,'Kanyon seyir noktasının kenar boyunca ahşap bir çiti var.'::text),
(294228,32692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanyoni kilátónak ... egy fakerítése a perem mentén.'::text,'van'::text,'van'::text,'van'::text,'A kanyoni kilátónak van egy fakerítése a perem mentén.'::text),
(294231,32693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Holzzaun ... am Rand des Canyons entlang.'::text,'verläuft'::text,'verlaufen'::text,'verlaufend'::text,'Der Holzzaun verläuft am Rand des Canyons entlang.'::text),
(294235,32693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дерев''яний паркан ... уздовж краю каньйону.'::text,'тягнеться'::text,'тягнутися'::text,'тягнучись'::text,'Дерев''яний паркан тягнеться уздовж краю каньйону.'::text),
(294234,32693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La valla de madera ... a lo largo del borde del cañón.'::text,'discurre'::text,'discurrir'::text,'discurriendo'::text,'La valla de madera discurre a lo largo del borde del cañón.'::text),
(294233,32693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clôture en bois ... le long du bord du canyon.'::text,'court'::text,'courir'::text,'courant'::text,'La clôture en bois court le long du bord du canyon.'::text),
(294236,32693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap çit kanyonun kenarı boyunca ...'::text,'uzanır'::text,'uzanmak'::text,'uzanarak'::text,'Ahşap çit kanyonun kenarı boyunca uzanır.'::text),
(294237,32693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fakerítés a kanyon peremén ... végig.'::text,'fut'::text,'futni'::text,'futó'::text,'A fakerítés a kanyon peremén fut végig.'::text),
(294240,32694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... vom Zaun aus alles sehen, kein Grund zu klettern.'::text,'kann'::text,'kann'::text,'kann'::text,'Bro, sie kann vom Zaun aus alles sehen, kein Grund zu klettern.'::text),
(294244,32694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... побачити все від паркану, лізти нікуди не треба.'::text,'може'::text,'може'::text,'може'::text,'Бро, вона може побачити все від паркану, лізти нікуди не треба.'::text),
(294243,32694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... verlo todo desde la valla, no hace falta trepar.'::text,'puede'::text,'puede'::text,'puede'::text,'Tío, ella puede verlo todo desde la valla, no hace falta trepar.'::text),
(294242,32694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... tout voir depuis la clôture, pas besoin de grimper.'::text,'peut'::text,'peut'::text,'peut'::text,'Frère, elle peut tout voir depuis la clôture, pas besoin de grimper.'::text),
(294245,32694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çitin oradan her şeyi ..., tırmanmaya gerek yok.'::text,'görebilir'::text,'görebilir'::text,'görebilir'::text,'Kanka, çitin oradan her şeyi görebilir, tırmanmaya gerek yok.'::text),
(294246,32694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kerítéstől mindent ..., nem kell mászni.'::text,'láthat'::text,'láthat'::text,'láthat'::text,'Tesó, a kerítéstől mindent láthat, nem kell mászni.'::text),
(294249,32695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, dieser Zaun ist ziemlich alt, er hat zehn hölzerne ...'::text,'Pfosten.'::text,'Pfosten.'::text,'Pfosten.'::text,'Nee, dieser Zaun ist ziemlich alt, er hat zehn hölzerne Pfosten.'::text),
(294253,32695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, цей паркан якийсь старий, у нього десять дерев''яних ...'::text,'стовпців.'::text,'стовпчик.'::text,'стовпців.'::text,'Не, цей паркан якийсь старий, у нього десять дерев''яних стовпців.'::text),
(294252,32695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, esta valla está algo vieja, tiene diez ... de madera.'::text,'postes'::text,'poste'::text,'postes'::text,'Qué va, esta valla está algo vieja, tiene diez postes de madera.'::text),
(294251,32695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, cette clôture est un peu vieille, elle a dix ... en bois.'::text,'poteaux'::text,'poteau'::text,'poteaux'::text,'Non, cette clôture est un peu vieille, elle a dix poteaux en bois.'::text),
(294254,32695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu çit biraz eski, ahşaptan on tane ...'::text,'direk.'::text,'direk.'::text,'direkler.'::text,'Yok, bu çit biraz eski, ahşaptan on tane direk.'::text),
(294255,32695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ez a kerítés elég régi, tíz fa ... van.'::text,'oszlopa'::text,'oszlopa'::text,'oszlopa'::text,'Á, ez a kerítés elég régi, tíz fa oszlopa van.'::text),
(294267,32697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie ... Zäune sind da? Einer, weil sie nur einen sehen kann.'::text,'viele'::text,'viel'::text,'einige'::text,'Wie viele Zäune sind da? Einer, weil sie nur einen sehen kann.'::text),
(294271,32697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... там парканів? Один, бо вона бачить лише один.'::text,'Скільки'::text,'Скільки'::text,'Декілька'::text,'Скільки там парканів? Один, бо вона бачить лише один.'::text),
(294270,32697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... vallas hay? Una, porque ella solo ve una.'::text,'Cuántas'::text,'Cuánta'::text,'Algunas'::text,'¿Cuántas vallas hay? Una, porque ella solo ve una.'::text),
(294269,32697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de clôtures y a-t-il ? Une, parce qu''elle n''en voit qu''une.'::text,'Combien'::text,'Combien'::text,'Quelques'::text,'Combien de clôtures y a-t-il ? Une, parce qu''elle n''en voit qu''une.'::text),
(294272,32697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orada ... çit var? Bir, çünkü sadece bir tane görebiliyor.'::text,'kaç'::text,'ne kadar'::text,'birkaç'::text,'Orada kaç çit var? Bir, çünkü sadece bir tane görebiliyor.'::text),
(294273,32697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kerítés van ott? Egy, mert csak egyet lát.'::text,'Hány'::text,'Mennyi'::text,'Néhány'::text,'Hány kerítés van ott? Egy, mert csak egyet lát.'::text),
(294285,32699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zaun sichert den Abgrund ab, ... bleibt sie dahinter.'::text,'also'::text,'aber'::text,'weil'::text,'Der Zaun sichert den Abgrund ab, also bleibt sie dahinter.'::text),
(294289,32699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Паркан відгороджує обрив, ... вона лишається за ним.'::text,'тому'::text,'але'::text,'бо'::text,'Паркан відгороджує обрив, тому вона лишається за ним.'::text),
(294288,32699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La valla cierra el paso al precipicio, ... ella se queda detrás.'::text,'así que'::text,'pero'::text,'porque'::text,'La valla cierra el paso al precipicio, así que ella se queda detrás.'::text),
(294287,32699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clôture ferme l''accès au vide, ... elle reste derrière.'::text,'donc'::text,'mais'::text,'parce que'::text,'La clôture ferme l''accès au vide, donc elle reste derrière.'::text),
(294290,32699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çit uçurumu kapatıyor ... o da arkasında kalıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Çit uçurumu kapatıyor bu yüzden o da arkasında kalıyor.'::text),
(294291,32699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kerítés elzárja a szakadékot, ... mögötte marad.'::text,'ezért'::text,'de'::text,'mert'::text,'A kerítés elzárja a szakadékot, ezért mögötte marad.'::text),
(308010,34224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Tor 4 führt zu ... Palast dort drüben.'::text,'jenem'::text,'diesem'::text,'jenen'::text,'Bericht: Tor 4 führt zu jenem Palast dort drüben.'::text),
(308014,34224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: брама 4 веде до ... палацу он там.'::text,'того'::text,'цього'::text,'тих'::text,'Звіт: брама 4 веде до того палацу он там.'::text),
(308013,34224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: la puerta 4 da a ... palacio de allí.'::text,'ese'::text,'este'::text,'esos'::text,'Informe: la puerta 4 da a ese palacio de allí.'::text),
(308012,34224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : la porte 4 donne sur ... palais là-bas.'::text,'ce'::text,'ce'::text,'ces'::text,'Rapport : la porte 4 donne sur ce palais là-bas.'::text),
(308015,34224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: 4 numaralı kapı oradaki ... saraya açılıyor.'::text,'şu'::text,'bu'::text,'şu'::text,'Rapor: 4 numaralı kapı oradaki şu saraya açılıyor.'::text),
(308016,34224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: a 4-es kapu ... a palotára nyílik ott.'::text,'arra'::text,'erre'::text,'azokra'::text,'Jelentés: a 4-es kapu arra a palotára nyílik ott.'::text),
(308019,34225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie öffnet das goldene Tor, also ist das ... Palast.'::text,'ihr'::text,'sein'::text,'sein'::text,'Sie öffnet das goldene Tor, also ist das ihr Palast.'::text),
(308023,34225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відчиняє золоту браму, отже, це ... палац.'::text,'її'::text,'його'::text,'його'::text,'Вона відчиняє золоту браму, отже, це її палац.'::text),
(308022,34225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella abre la puerta dorada, así que ese es ... palacio.'::text,'su'::text,'su'::text,'su'::text,'Ella abre la puerta dorada, así que ese es su palacio.'::text),
(308021,34225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ouvre la porte dorée, donc c''est ... palais.'::text,'son'::text,'son'::text,'son'::text,'Elle ouvre la porte dorée, donc c''est son palais.'::text),
(308024,34225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altın kapıyı açıyor, demek ki bu ... sarayı.'::text,'onun'::text,'onun'::text,'onun'::text,'Altın kapıyı açıyor, demek ki bu onun sarayı.'::text),
(308025,34225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kinyitja az aranykaput, tehát az ott a ...'::text,'palotája'::text,'palotája'::text,'palotája'::text,'Kinyitja az aranykaput, tehát az ott a palotája.'::text),
(308028,34226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist dein Palast? Hinter diesem goldenen Tor? Ehrlich, so cool.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo ist dein Palast? Hinter diesem goldenen Tor? Ehrlich, so cool.'::text),
(308032,34226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... твій палац? За тією золотою брамою? Чесно, так круто.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де твій палац? За тією золотою брамою? Чесно, так круто.'::text),
(308031,34226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está tu palacio? ¿Detrás de esa puerta dorada? En serio, qué guay.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde está tu palacio? ¿Detrás de esa puerta dorada? En serio, qué guay.'::text),
(308030,34226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est ton palais ? Derrière cette porte dorée ? Franchement, trop cool.'::text,'Où'::text,'Quoi'::text,'Qui'::text,'Où est ton palais ? Derrière cette porte dorée ? Franchement, trop cool.'::text),
(308033,34226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarayın ...? O altın kapının arkasında mı? Cidden, çok havalı.'::text,'nerede'::text,'ne'::text,'kim'::text,'Sarayın nerede? O altın kapının arkasında mı? Cidden, çok havalı.'::text),
(308034,34226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a palotád? Amögött az aranykapu mögött? Őszintén, nagyon menő.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol van a palotád? Amögött az aranykapu mögött? Őszintén, nagyon menő.'::text),
(308037,34227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie du ... dem Palast lächelst, als ob du dort wohnst.'::text,'vor'::text,'auf'::text,'an'::text,'Wie du vor dem Palast lächelst, als ob du dort wohnst.'::text),
(308041,34227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Те, як ти усміхаєшся ... палацом, ніби ти там живеш.'::text,'перед'::text,'на'::text,'біля'::text,'Те, як ти усміхаєшся перед палацом, ніби ти там живеш.'::text),
(308040,34227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cómo sonríes ... del palacio, como si vivieras allí.'::text,'delante'::text,'sobre'::text,'a'::text,'Cómo sonríes delante del palacio, como si vivieras allí.'::text),
(308039,34227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ta façon de sourire ... palais, comme si tu y habitais.'::text,'devant le'::text,'sur le'::text,'au'::text,'Ta façon de sourire devant le palais, comme si tu y habitais.'::text),
(308042,34227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarayın ... gülümseyişin, sanki orada yaşıyormuşsun gibi.'::text,'önünde'::text,'üstünde'::text,NULL::text,'Sarayın önünde gülümseyişin, sanki orada yaşıyormuşsun gibi.'::text),
(308043,34227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy ... mosolyogsz, mintha ott laknál.'::text,'a palota előtt'::text,'a palotán'::text,'a palotánál'::text,'Ahogy a palota előtt mosolyogsz, mintha ott laknál.'::text),
(308064,34230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst öffnet sie Gartentore, aber gestern ... sie ein Palasttor.'::text,'öffnete'::text,'öffnet'::text,NULL::text,'Sonst öffnet sie Gartentore, aber gestern öffnete sie ein Palasttor.'::text),
(308068,34230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона відчиняє садові хвіртки, але вчора ... браму палацу.'::text,'відчинила'::text,'відчиняє'::text,NULL::text,'Зазвичай вона відчиняє садові хвіртки, але вчора відчинила браму палацу.'::text),
(308067,34230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente abre puertas de jardín, pero ayer ... la puerta de un palacio.'::text,'abrió'::text,'abre'::text,NULL::text,'Normalmente abre puertas de jardín, pero ayer abrió la puerta de un palacio.'::text),
(308066,34230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle ouvre des portes de jardin, mais hier elle ... une porte de palais.'::text,'a ouvert'::text,'ouvre'::text,NULL::text,'D''habitude elle ouvre des portes de jardin, mais hier elle a ouvert une porte de palais.'::text),
(308069,34230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde bahçe kapılarını açar ama dün bir saray kapısı ...'::text,'açtı'::text,'açar'::text,NULL::text,'Genelde bahçe kapılarını açar ama dün bir saray kapısı açtı.'::text),
(308070,34230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában kertkapukat nyit ki, de tegnap egy palotakaput ... ki.'::text,'nyitott'::text,'nyit'::text,NULL::text,'Általában kertkapukat nyit ki, de tegnap egy palotakaput nyitott ki.'::text),
(308073,34231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... durch das goldene Tor auf einen Palast, ohne Witz.'::text,'schaut'::text,'schaut'::text,'schaut'::text,'Bro, sie schaut durch das goldene Tor auf einen Palast, ohne Witz.'::text),
(308077,34231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... крізь золоту браму на палац, без жартів.'::text,'дивиться'::text,'дивиться'::text,'дивиться'::text,'Бро, вона дивиться крізь золоту браму на палац, без жартів.'::text),
(308076,34231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... un palacio a través de la puerta dorada, en serio.'::text,'está mirando'::text,'mira'::text,'está mirando'::text,'Tío, ella está mirando un palacio a través de la puerta dorada, en serio.'::text),
(308075,34231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... un palais à travers la porte dorée, sans mentir.'::text,'est en train de regarder'::text,'regarde'::text,'est en train de regarder'::text,'Frère, elle est en train de regarder un palais à travers la porte dorée, sans mentir.'::text),
(308078,34231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, altın kapının arasından bir saraya ..., yemin ederim.'::text,'bakıyor'::text,'bakar'::text,'bakıyor'::text,'Kanka, altın kapının arasından bir saraya bakıyor, yemin ederim.'::text),
(308079,34231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az aranykapun át egy palotát ..., komolyan.'::text,'néz'::text,'néz'::text,'néz'::text,'Tesó, az aranykapun át egy palotát néz, komolyan.'::text),
(299649,33295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er ist immer hilfsbereit, und gerade ... er den Schal einer Frau auf.'::text,'hebt'::text,'hebt'::text,NULL::text,'Bestie, ich hab gehört, er ist immer hilfsbereit, und gerade hebt er den Schal einer Frau auf.'::text),
(299653,33295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, він завжди готовий допомогти, і саме зараз він ... шарф якоїсь жінки.'::text,'піднімає'::text,'піднімає'::text,NULL::text,'Подруго, я чула, він завжди готовий допомогти, і саме зараз він піднімає шарф якоїсь жінки.'::text),
(299652,33295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que siempre es muy servicial, y ahora mismo ... el pañuelo de una mujer.'::text,'está recogiendo'::text,'recoge'::text,NULL::text,'Amiga, he oído que siempre es muy servicial, y ahora mismo está recogiendo el pañuelo de una mujer.'::text),
(299651,33295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''il est toujours serviable, et là il ... l''écharpe d''une femme.'::text,'est en train de ramasser'::text,'ramasse'::text,NULL::text,'Ma belle, il paraît qu''il est toujours serviable, et là il est en train de ramasser l''écharpe d''une femme.'::text),
(299654,33295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki hep yardımseverdir, şu an da bir kadının atkısını ...'::text,'yerden alıyor'::text,'yerden alır'::text,NULL::text,'Kızım, duydum ki hep yardımseverdir, şu an da bir kadının atkısını yerden alıyor.'::text),
(299655,33295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy mindig segítőkész, és most épp ... egy nő sálját.'::text,'felveszi'::text,'felveszi'::text,NULL::text,'Csajszi, azt hallottam, hogy mindig segítőkész, és most épp felveszi egy nő sálját.'::text),
(299658,33296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal: Angeblich heißt es, dass er morgen wieder hilfsbereit zu ihr ...'::text,'sein wird'::text,'ist'::text,'sein'::text,'Rate mal: Angeblich heißt es, dass er morgen wieder hilfsbereit zu ihr sein wird.'::text),
(299662,33296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, він завтра знову ... готовий їй допомогти.'::text,'буде'::text,'є'::text,'бути'::text,'Уяви, кажуть, він завтра знову буде готовий їй допомогти.'::text),
(299661,33296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, parece que mañana él ... servicial con ella otra vez.'::text,'será'::text,'es'::text,'ser'::text,'Adivina, parece que mañana él será servicial con ella otra vez.'::text),
(299660,33296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment il ... serviable avec elle encore demain.'::text,'sera'::text,'est'::text,'être'::text,'Devine quoi, apparemment il sera serviable avec elle encore demain.'::text),
(299663,33296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, galiba yarın yine ona yardımsever ...'::text,'olacak'::text,NULL::text,'olmak'::text,'Tahmin et ne oldu, galiba yarın yine ona yardımsever olacak.'::text),
(299664,33296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag holnap is segítőkész ... vele.'::text,'lesz'::text,NULL::text,'lenni'::text,'Képzeld, állítólag holnap is segítőkész lesz vele.'::text),
(299667,33297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, er hat mir gesagt, er ... ihre schweren Taschen tragen. So hilfsbereit.'::text,'wird'::text,'wird'::text,'werden'::text,'Okay, also, er hat mir gesagt, er wird ihre schweren Taschen tragen. So hilfsbereit.'::text),
(299671,33297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що ... понести її важкі сумки. Такий чуйний.'::text,'збирається'::text,'збирається'::text,'збираються'::text,'Коротше, він сказав мені, що збирається понести її важкі сумки. Такий чуйний.'::text),
(299670,33297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me dijo que ... llevarle las bolsas pesadas. Qué servicial.'::text,'va a'::text,'va a'::text,'van a'::text,'Vale, me dijo que va a llevarle las bolsas pesadas. Qué servicial.'::text),
(299669,33297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, il m''a dit qu''il ... porter ses sacs lourds. Trop serviable.'::text,'va'::text,'va'::text,'vont'::text,'Bon alors, il m''a dit qu''il va porter ses sacs lourds. Trop serviable.'::text),
(299672,33297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, bana dedi ki kadının ağır çantalarını ..., çok yardımsever.'::text,'taşıyacak'::text,'taşıyacak'::text,'taşıyacaklar'::text,'Neyse, bana dedi ki kadının ağır çantalarını taşıyacak, çok yardımsever.'::text),
(299673,33297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy el ... vinni a nehéz szatyrait. Olyan segítőkész.'::text,'fogja'::text,'fogja'::text,'fogják'::text,'Szóval azt mondta, hogy el fogja vinni a nehéz szatyrait. Olyan segítőkész.'::text),
(299685,33299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ... als alle anderen an der Tramhaltestelle.'::text,'hilfsbereiter'::text,'hilfsbereiter'::text,'am hilfsbereitesten'::text,'Ehrlich, du bist hilfsbereiter als alle anderen an der Tramhaltestelle.'::text),
(299689,33299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... за всіх інших на трамвайній зупинці.'::text,'більш чуйний'::text,'чуйніший'::text,'найчуйніший'::text,'Чесно, ти більш чуйний за всіх інших на трамвайній зупинці.'::text),
(299688,33299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, eres ... que todos los demás en la parada del tranvía.'::text,'más servicial'::text,'más servicial'::text,'el más servicial'::text,'En serio, eres más servicial que todos los demás en la parada del tranvía.'::text),
(299687,33299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... que tous les autres à l''arrêt de tram.'::text,'plus serviable'::text,'plus serviable'::text,'le plus serviable'::text,'Franchement, tu es plus serviable que tous les autres à l''arrêt de tram.'::text),
(299690,33299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen tramvay durağındaki herkesten ...'::text,'daha yardımseversin'::text,'daha yardımseversin'::text,'en yardımseversin'::text,'Açıkçası sen tramvay durağındaki herkesten daha yardımseversin.'::text),
(299691,33299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... vagy, mint bárki más a villamosmegállóban.'::text,'segítőkészebb'::text,'segítőkészebb'::text,'legsegítőkészebb'::text,'Őszintén, segítőkészebb vagy, mint bárki más a villamosmegállóban.'::text),
(299694,33300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Er sagt sich, er ... zu jedem Fremden hilfsbereit sein.'::text,'muss'::text,'muss'::text,'sollte'::text,'Ein echter Profi: Er sagt sich, er muss zu jedem Fremden hilfsbereit sein.'::text),
(299698,33300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі: він каже собі, що ... бути чуйним до кожного незнайомця.'::text,'мусить'::text,'має'::text,'мав би'::text,'Справжній профі: він каже собі, що мусить бути чуйним до кожного незнайомця.'::text),
(299697,33300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: se dice a sí mismo que ... ser servicial con cada desconocido.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Todo un profesional: se dice a sí mismo que debe ser servicial con cada desconocido.'::text),
(299696,33300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : il se dit qu''il ... être serviable avec chaque inconnu.'::text,'doit'::text,'doit'::text,'devrait'::text,'Un vrai pro : il se dit qu''il doit être serviable avec chaque inconnu.'::text),
(299699,33300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: kendine her yabancıya karşı yardımsever ... diyor.'::text,'olmalı'::text,'olmak zorunda'::text,'olmalı'::text,'Tam bir profesyonel: kendine her yabancıya karşı yardımsever olmalı diyor.'::text),
(299700,33300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: azt mondja magának, hogy minden idegennel segítőkésznek ... lennie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Igazi profi: azt mondja magának, hogy minden idegennel segítőkésznek kell lennie.'::text),
(299703,33301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist hilfsbereit und hält die Tür des Cafés ... auf.'::text,'höflich'::text,'höflich'::text,'Höflichkeit'::text,'Er ist hilfsbereit und hält die Tür des Cafés höflich auf.'::text),
(299707,33301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він чуйний і ... тримає двері кафе відчиненими.'::text,'ввічливо'::text,'ввічливий'::text,'ввічливість'::text,'Він чуйний і ввічливо тримає двері кафе відчиненими.'::text),
(299706,33301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es servicial y sujeta la puerta de la cafetería ...'::text,'educadamente.'::text,'educado.'::text,'educación.'::text,'Es servicial y sujeta la puerta de la cafetería educadamente.'::text),
(299705,33301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est serviable et tient la porte du café ...'::text,'poliment.'::text,'poli.'::text,'politesse.'::text,'Il est serviable et tient la porte du café poliment.'::text),
(299708,33301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yardımsever ve kafenin kapısını ... açık tutuyor.'::text,'kibarca'::text,'kibar'::text,'kibarlık'::text,'Yardımsever ve kafenin kapısını kibarca açık tutuyor.'::text),
(299709,33301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Segítőkész, és ... tartja nyitva a kávézó ajtaját.'::text,'udvariasan'::text,'udvarias'::text,'udvariasság'::text,'Segítőkész, és udvariasan tartja nyitva a kávézó ajtaját.'::text),
(296679,32965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber du ... das schönste Lächeln in ganz Deutschland.'::text,'hast'::text,'hat'::text,'bist'::text,'Okay, aber du hast das schönste Lächeln in ganz Deutschland.'::text),
(296683,32965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але ти ... найкращу усмішку в усій Німеччині.'::text,'маєш'::text,'має'::text,'є'::text,'Окей, але ти маєш найкращу усмішку в усій Німеччині.'::text),
(296682,32965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero tú ... la mejor sonrisa de toda Alemania.'::text,'tienes'::text,'tiene'::text,'estás'::text,'Vale, pero tú tienes la mejor sonrisa de toda Alemania.'::text),
(296681,32965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'OK, mais tu ... le plus beau sourire de toute l''Allemagne.'::text,'as'::text,'a'::text,'es'::text,'OK, mais tu as le plus beau sourire de toute l''Allemagne.'::text),
(296684,32965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama bütün Almanya''daki en güzel gülümseme sende ...'::text,'var'::text,'var'::text,NULL::text,'Tamam ama bütün Almanya''daki en güzel gülümseme sende var.'::text),
(296685,32965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de neked ... a legszebb mosolyod egész Németországban.'::text,'van'::text,'van'::text,'van'::text,'Oké, de neked van a legszebb mosolyod egész Németországban.'::text),
(296697,32967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Von der Steinmauer aus ... er eine Burg in Deutschland sehen.'::text,'kann'::text,'kann'::text,'kann'::text,'Von der Steinmauer aus kann er eine Burg in Deutschland sehen.'::text),
(296701,32967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З кам''яної стіни він ... побачити замок у Німеччині.'::text,'може'::text,'може'::text,'може'::text,'З кам''яної стіни він може побачити замок у Німеччині.'::text),
(296700,32967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde el muro de piedra él ... ver un castillo en Alemania.'::text,'puede'::text,'puede'::text,'puede'::text,'Desde el muro de piedra él puede ver un castillo en Alemania.'::text),
(296699,32967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis le mur en pierre, il ... voir un château en Allemagne.'::text,'peut'::text,'peut'::text,'peut'::text,'Depuis le mur en pierre, il peut voir un château en Allemagne.'::text),
(296702,32967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taş duvardan Almanya''da bir şato ...'::text,'görebilir'::text,'görebilir'::text,'görebilir'::text,'Taş duvardan Almanya''da bir şato görebilir.'::text),
(296703,32967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kőfalról ... egy kastélyt Németországban.'::text,'láthat'::text,'láthat'::text,'láthat'::text,'A kőfalról láthat egy kastélyt Németországban.'::text),
(296706,32968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In Deutschland heben die Männer an seinem Tisch große steinerne ...'::text,'Becher.'::text,'Becher.'::text,'Becher.'::text,'In Deutschland heben die Männer an seinem Tisch große steinerne Becher.'::text),
(296710,32968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У Німеччині чоловіки за його столом піднімають великі кам''яні ...'::text,'кухлі.'::text,'кухоль.'::text,'кухлі.'::text,'У Німеччині чоловіки за його столом піднімають великі кам''яні кухлі.'::text),
(296709,32968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En Alemania, los hombres de su mesa levantan grandes ... de piedra.'::text,'tazas'::text,'taza'::text,'tazas'::text,'En Alemania, los hombres de su mesa levantan grandes tazas de piedra.'::text),
(296708,32968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En Allemagne, les hommes à sa table lèvent de grands ... en grès.'::text,'mugs'::text,'mug'::text,'mugs'::text,'En Allemagne, les hommes à sa table lèvent de grands mugs en grès.'::text),
(296711,32968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Almanya''da masasındaki adamlar büyük taş ... kaldırıyor.'::text,'kupaları'::text,'kupayı'::text,'kupaları'::text,'Almanya''da masasındaki adamlar büyük taş kupaları kaldırıyor.'::text),
(296712,32968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Németországban az asztalánál ülő férfiak nagy, kőből készült ...'::text,'bögréket.'::text,'bögrét.'::text,'bögréket.'::text,'Németországban az asztalánál ülő férfiak nagy, kőből készült bögréket.'::text),
(296724,32970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In Deutschland ... ein weißes Schloss im Nebel.'::text,'ist'::text,'sind'::text,'sein'::text,'In Deutschland ist ein weißes Schloss im Nebel.'::text),
(296728,32970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У Німеччині ... білий замок у тумані.'::text,'є'::text,'є'::text,'бути'::text,'У Німеччині є білий замок у тумані.'::text),
(296727,32970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En Alemania ... un castillo blanco entre la niebla.'::text,'hay'::text,'hay'::text,'hay'::text,'En Alemania hay un castillo blanco entre la niebla.'::text),
(296726,32970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En Allemagne, ... un château blanc dans la brume.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'En Allemagne, il y a un château blanc dans la brume.'::text),
(296729,32970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Almanya''da siste beyaz bir şato ...'::text,'var'::text,'var'::text,'olmak'::text,'Almanya''da siste beyaz bir şato var.'::text),
(296730,32970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Németországban ... egy fehér kastély a ködben.'::text,'van'::text,'vannak'::text,'lenni'::text,'Németországban van egy fehér kastély a ködben.'::text),
(296733,32971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Besucher in Deutschland ... das Brandenburger Tor in Berlin sehen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Besucher in Deutschland sollten das Brandenburger Tor in Berlin sehen.'::text),
(296737,32971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туристи в Німеччині ... побачити Бранденбурзькі ворота в Берліні.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Туристи в Німеччині мали б побачити Бранденбурзькі ворота в Берліні.'::text),
(296736,32971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los visitantes de Alemania ... ver la Puerta de Brandeburgo en Berlín.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'Los visitantes de Alemania deberían ver la Puerta de Brandeburgo en Berlín.'::text),
(296735,32971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs en Allemagne ... voir la porte de Brandebourg à Berlin.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Les visiteurs en Allemagne devraient voir la porte de Brandebourg à Berlin.'::text),
(296738,32971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Almanya''ya gelenler Berlin''deki Brandenburg Kapısı''nı ...'::text,'görmeli'::text,'görmeli'::text,'görmeli'::text,'Almanya''ya gelenler Berlin''deki Brandenburg Kapısı''nı görmeli.'::text),
(296739,32971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A Németországba látogatóknak ... megnézniük a berlini Brandenburgi kaput.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'A Németországba látogatóknak kellene megnézniük a berlini Brandenburgi kaput.'::text),
(296742,32972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, ich hab gehört, er ist nach Deutschland gefahren, ... er Burgen liebt.'::text,'weil'::text,'aber'::text,'also'::text,'Süße, ich hab gehört, er ist nach Deutschland gefahren, weil er Burgen liebt.'::text),
(296746,32972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, він поїхав до Німеччини, ... обожнює замки.'::text,'бо'::text,'але'::text,'тому'::text,'Подруго, я чула, він поїхав до Німеччини, бо обожнює замки.'::text),
(296745,32972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que se fue a Alemania ... le encantan los castillos.'::text,'porque'::text,'pero'::text,'así que'::text,'Tía, he oído que se fue a Alemania porque le encantan los castillos.'::text),
(296744,32972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''il est allé en Allemagne ... adore les châteaux.'::text,'parce qu''il'::text,'mais il'::text,'donc il'::text,'Ma belle, il paraît qu''il est allé en Allemagne parce qu''il adore les châteaux.'::text),
(296747,32972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki Almanya''ya gitmiş ... şatolara bayılıyor.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Kızım, duydum ki Almanya''ya gitmiş çünkü şatolara bayılıyor.'::text),
(296748,32972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy Németországba ment, ... imádja a kastélyokat.'::text,'mert'::text,'de'::text,'ezért'::text,'Csajszi, azt hallottam, hogy Németországba ment, mert imádja a kastélyokat.'::text),
(315120,35014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekte Ehe, klar. Gerade ... sie durch getrennte Türen.'::text,'gehen'::text,'gehen'::text,NULL::text,'Perfekte Ehe, klar. Gerade gehen sie durch getrennte Türen.'::text),
(315124,35014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальний шлюб, звісно. Саме зараз вони ... через окремі двері.'::text,'виходять'::text,'виходять'::text,NULL::text,'Ідеальний шлюб, звісно. Саме зараз вони виходять через окремі двері.'::text),
(315123,35014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Matrimonio perfecto, obviamente. Ahora mismo ... por puertas separadas.'::text,'están saliendo'::text,'salen'::text,NULL::text,'Matrimonio perfecto, obviamente. Ahora mismo están saliendo por puertas separadas.'::text),
(315122,35014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mariage parfait, évidemment. En ce moment, ils ... par des portes séparées.'::text,'sont en train de sortir'::text,'sortent'::text,NULL::text,'Mariage parfait, évidemment. En ce moment, ils sont en train de sortir par des portes séparées.'::text),
(315125,35014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz evlilik, belli. Şu an ayrı kapılardan ...'::text,'çıkıyorlar'::text,'çıkarlar'::text,NULL::text,'Kusursuz evlilik, belli. Şu an ayrı kapılardan çıkıyorlar.'::text),
(315126,35014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes házasság, nyilván. Most épp külön ajtókon ... ki.'::text,'mennek'::text,'mennek'::text,NULL::text,'Tökéletes házasság, nyilván. Most épp külön ajtókon mennek ki.'::text),
(315129,35015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... bald in getrennten Wohnungen wohnen, ohne Witz.'::text,'werden'::text,'sind'::text,'gehen'::text,'Bro, sie werden bald in getrennten Wohnungen wohnen, ohne Witz.'::text),
(315133,35015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони скоро ... жити в окремих квартирах, без жартів.'::text,'будуть'::text,'є'::text,'ідуть'::text,'Бро, вони скоро будуть жити в окремих квартирах, без жартів.'::text),
(315132,35015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, pronto ... vivir en pisos separados, en serio.'::text,''::text,'están'::text,'van'::text,'Tío, pronto vivir en pisos separados, en serio.'::text),
(315131,35015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ils ... vivre dans des apparts séparés bientôt, sans mentir.'::text,''::text,'sont'::text,'vont'::text,'Frère, ils vivre dans des apparts séparés bientôt, sans mentir.'::text),
(315134,35015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yakında ayrı evlerde ..., cidden.'::text,'yaşayacaklar'::text,NULL::text,'gidiyorlar'::text,'Kanka, yakında ayrı evlerde yaşayacaklar, cidden.'::text),
(315135,35015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, hamarosan külön lakásban ... lakni, komolyan.'::text,'fognak'::text,'vannak'::text,'mennek'::text,'Tesó, hamarosan külön lakásban fognak lakni, komolyan.'::text),
(315138,35016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, sie haben einen Plan, sie ... getrennte Wohnungen nehmen, echt.'::text,'werden'::text,'werden'::text,'sind'::text,'Nee, sie haben einen Plan, sie werden getrennte Wohnungen nehmen, echt.'::text),
(315142,35016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, у них є план, вони ... взяти окремі квартири, чесно.'::text,'збираються'::text,'будуть'::text,'є'::text,'Не, у них є план, вони збираються взяти окремі квартири, чесно.'::text),
(315141,35016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tienen un plan, ... pillar pisos separados, en serio.'::text,'van a'::text,NULL::text,'están'::text,'Qué va, tienen un plan, van a pillar pisos separados, en serio.'::text),
(315140,35016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, ils ont un plan, ils ... prendre des apparts séparés, sérieux.'::text,'vont'::text,NULL::text,'sont'::text,'Non, ils ont un plan, ils vont prendre des apparts séparés, sérieux.'::text),
(315143,35016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, planları var, ayrı evler ..., cidden.'::text,'tutacaklar'::text,'tutacaklar'::text,NULL::text,'Yok, planları var, ayrı evler tutacaklar, cidden.'::text),
(315144,35016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, van tervük, külön lakást ... szerezni, komolyan.'::text,'fognak'::text,'fognak'::text,'vannak'::text,'Á, van tervük, külön lakást fognak szerezni, komolyan.'::text),
(315156,35018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Leben sind jetzt ... als letztes Jahr.'::text,'getrennter'::text,'getrennter'::text,'am getrenntesten'::text,'Ihre Leben sind jetzt getrennter als letztes Jahr.'::text),
(315160,35018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхні життя тепер ..., ніж торік.'::text,'більш роздільні'::text,'роздільніші'::text,'найроздільніші'::text,'Їхні життя тепер більш роздільні, ніж торік.'::text),
(315159,35018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus vidas están ... ahora que el año pasado.'::text,'más separadas'::text,'más separadas'::text,'las más separadas'::text,'Sus vidas están más separadas ahora que el año pasado.'::text),
(315158,35018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leurs vies sont ... maintenant que l''an dernier.'::text,'plus séparées'::text,'plus séparées'::text,'les plus séparées'::text,'Leurs vies sont plus séparées maintenant que l''an dernier.'::text),
(315161,35018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatları artık geçen yıldan ...'::text,'daha ayrı'::text,'daha ayrı'::text,'en ayrı'::text,'Hayatları artık geçen yıldan daha ayrı.'::text),
(315162,35018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az életük most ..., mint tavaly.'::text,'különállóbb'::text,'különállóbb'::text,'legkülönállóbb'::text,'Az életük most különállóbb, mint tavaly.'::text),
(315165,35019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regel sagt, du ... ein separates Blatt unterschreiben. Ehrlich, so entspannt.'::text,'musst'::text,'musst'::text,'solltest'::text,'Die Regel sagt, du musst ein separates Blatt unterschreiben. Ehrlich, so entspannt.'::text),
(315169,35019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За правилом ти ... підписати окремий папір. Чесно, так спокійно.'::text,'маєш'::text,'мусиш'::text,'мав би'::text,'За правилом ти маєш підписати окремий папір. Чесно, так спокійно.'::text),
(315168,35019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La norma dice que ... firmar un papel aparte. En serio, qué calma.'::text,'tienes que'::text,'debes'::text,'deberías'::text,'La norma dice que tienes que firmar un papel aparte. En serio, qué calma.'::text),
(315167,35019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La règle dit que tu ... signer un papier séparé. Franchement, trop calme.'::text,'dois'::text,'dois'::text,'devrais'::text,'La règle dit que tu dois signer un papier séparé. Franchement, trop calme.'::text),
(315170,35019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurala göre ayrı bir kâğıt ..., cidden, çok sakin.'::text,'imzalamak zorundasın'::text,'imzalamalısın'::text,'imzalamalısın'::text,'Kurala göre ayrı bir kâğıt imzalamak zorundasın, cidden, çok sakin.'::text),
(315171,35019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szabály szerint egy külön papírt ... aláírnod. Őszintén, olyan nyugodt.'::text,'kell'::text,'kell'::text,'kellene'::text,'A szabály szerint egy külön papírt kell aláírnod. Őszintén, olyan nyugodt.'::text),
(315174,35020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du gehst ... durch deine eigene Tür hinaus. Respekt.'::text,'ruhig'::text,'ruhig'::text,'Ruhe'::text,'Du gehst ruhig durch deine eigene Tür hinaus. Respekt.'::text),
(315178,35020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... виходиш через свої окремі двері. Респект.'::text,'спокійно'::text,'спокійний'::text,'спокій'::text,'Ти спокійно виходиш через свої окремі двері. Респект.'::text),
(315177,35020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sales ... por tu puerta aparte. Respeto.'::text,'tranquilamente'::text,'tranquilo'::text,'tranquilidad'::text,'Sales tranquilamente por tu puerta aparte. Respeto.'::text),
(315176,35020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu sors ... par ta porte séparée. Respect.'::text,'calmement'::text,'calme'::text,'calme'::text,'Tu sors calmement par ta porte séparée. Respect.'::text),
(315179,35020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi ayrı kapından ... çıkıyorsun. Saygılar.'::text,'sakince'::text,'sakin'::text,'sakinlik'::text,'Kendi ayrı kapından sakince çıkıyorsun. Saygılar.'::text),
(315180,35020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sétálsz ki a külön ajtódon. Respekt.'::text,'Nyugodtan'::text,'Nyugodt'::text,'Nyugalom'::text,'Nyugodtan sétálsz ki a külön ajtódon. Respekt.'::text),
(304725,33859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne Witz, sie ... unter diesem Blumenbogen, und es war echt stark.'::text,'heirateten'::text,'heiraten'::text,'heiratet'::text,'Ohne Witz, sie heirateten unter diesem Blumenbogen, und es war echt stark.'::text),
(304729,33859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без жартів, вони ... під тією квітковою аркою, і це було просто вогонь.'::text,'одружилися'::text,'одружуються'::text,'одружується'::text,'Без жартів, вони одружилися під тією квітковою аркою, і це було просто вогонь.'::text),
(304728,33859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ... bajo ese arco de flores y quedó brutal.'::text,'se casaron'::text,'se casan'::text,'se casa'::text,'En serio, se casaron bajo ese arco de flores y quedó brutal.'::text),
(304727,33859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ils ... sous cette arche fleurie et c''était trop stylé.'::text,'se sont mariés'::text,'se marient'::text,'se marie'::text,'Sans mentir, ils se sont mariés sous cette arche fleurie et c''était trop stylé.'::text),
(304730,33859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim, o çiçekli kemerin altında ... ve resmen ortalığı yıktı.'::text,'evlendiler'::text,'evlenirler'::text,'evlenir'::text,'Yemin ederim, o çiçekli kemerin altında evlendiler ve resmen ortalığı yıktı.'::text),
