(303820,33758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи сиру — це небагато, тож тепер він ... весь брусок.'::text,'натирає'::text,'натирає'::text,NULL::text,'Трохи сиру — це небагато, тож тепер він натирає весь брусок.'::text),
