(303818,33758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu de fromage, ce n''est pas beaucoup, donc maintenant il ... tout le bloc.'::text,'est en train de râper'::text,'râpe'::text,NULL::text,'Un peu de fromage, ce n''est pas beaucoup, donc maintenant il est en train de râper tout le bloc.'::text),
(303821,33758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz peynir çok değildir, bu yüzden şimdi bütün kalıbı ...'::text,'rendeliyor'::text,'rendeler'::text,NULL::text,'Biraz peynir çok değildir, bu yüzden şimdi bütün kalıbı rendeliyor.'::text),
(303822,33758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kis sajt nem sok, ezért most az egész tömböt ...'::text,'reszeli'::text,'reszeli'::text,NULL::text,'Egy kis sajt nem sok, ezért most az egész tömböt reszeli.'::text),
(303825,33759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur ein bisschen Käse? Nein! Er ... die Pasta für immer begraben!'::text,'wird'::text,'ist'::text,NULL::text,'Nur ein bisschen Käse? Nein! Er wird die Pasta für immer begraben!'::text),
