(303828,33759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Solo un poco de queso? ¡No! ¡Él ... enterrar la pasta para siempre!'::text,''::text,'está'::text,NULL::text,'¿Solo un poco de queso? ¡No! ¡Él enterrar la pasta para siempre!'::text),
(303827,33759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Juste un peu de fromage ? Non ! Il ... enterrer les pâtes pour toujours !'::text,''::text,'est'::text,NULL::text,'Juste un peu de fromage ? Non ! Il enterrer les pâtes pour toujours !'::text),
