(303834,33760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gast will ein bisschen Käse, aber er ... alles reiben.'::text,'wird'::text,'werden'::text,'wird'::text,'Der Gast will ein bisschen Käse, aber er wird alles reiben.'::text),
(303838,33760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гість хоче трохи сиру, але він ... натерти весь.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Гість хоче трохи сиру, але він збирається натерти весь.'::text),
