(303836,33760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client veut un peu de fromage, mais il ... tout râper.'::text,'va'::text,'vont'::text,'va'::text,'Le client veut un peu de fromage, mais il va tout râper.'::text),
(303839,33760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri biraz peynir istiyor ama o hepsini ...'::text,'rendeleyecek'::text,'rendeleyecekler'::text,'rendeleyecek'::text,'Müşteri biraz peynir istiyor ama o hepsini rendeleyecek.'::text),
(303840,33760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég egy kis sajtot kér, de ő az egészet le ... reszelni.'::text,'fogja'::text,'fogják'::text,'fogja'::text,'A vendég egy kis sajtot kér, de ő az egészet le fogja reszelni.'::text),
(303852,33762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos: Das ist ein bisschen Käse, ... als die Weingläser.'::text,'höher'::text,'höher'::text,'am höchsten'::text,'Makellos: Das ist ein bisschen Käse, höher als die Weingläser.'::text),
(303856,33762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно: оце трохи сиру — ... за винні келихи.'::text,'вищий'::text,'більш високий'::text,'найвищий'::text,'Бездоганно: оце трохи сиру — вищий за винні келихи.'::text),
(303855,33762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable: eso es un poco de queso, ... que las copas de vino.'::text,'más alto'::text,'más alto'::text,'el más alto'::text,'Impecable: eso es un poco de queso, más alto que las copas de vino.'::text),
(303854,33762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable : ça, c''est un peu de fromage, ... que les verres à vin.'::text,'plus haut'::text,'plus haut'::text,'le plus haut'::text,'Impeccable : ça, c''est un peu de fromage, plus haut que les verres à vin.'::text),
(303857,33762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz: işte biraz peynir, şarap kadehlerinden ...'::text,'daha yüksek'::text,'daha yüksek'::text,'en yüksek'::text,'Kusursuz: işte biraz peynir, şarap kadehlerinden daha yüksek.'::text),
(303858,33762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan: ez aztán egy kis sajt, ... a borospoharaknál.'::text,'magasabb'::text,'magasabb'::text,'legmagasabb'::text,'Hibátlan: ez aztán egy kis sajt, magasabb a borospoharaknál.'::text),
(303861,33763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Gast hat ein bisschen Käse gesagt, also ... er aufhören, echt.'::text,'muss'::text,'muss'::text,'sollte'::text,'Bro, der Gast hat ein bisschen Käse gesagt, also muss er aufhören, echt.'::text),
(303865,33763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, гість сказав трохи сиру, тож він ... зупинитися, чесно.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бро, гість сказав трохи сиру, тож він має зупинитися, чесно.'::text),
(303864,33763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el cliente dijo un poco de queso, así que ... parar, en serio.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, el cliente dijo un poco de queso, así que tiene que parar, en serio.'::text),
(303863,33763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le client a dit un peu de fromage, donc il ... arrêter, sérieux.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, le client a dit un peu de fromage, donc il doit arrêter, sérieux.'::text),
(303866,33763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, müşteri biraz peynir dedi, yani ..., cidden.'::text,'durmak zorunda'::text,'durmalı'::text,'durmalı'::text,'Kanka, müşteri biraz peynir dedi, yani durmak zorunda, cidden.'::text),
(303867,33763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a vendég egy kis sajtot mondott, szóval abba ... hagynia, komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, a vendég egy kis sajtot mondott, szóval abba kell hagynia, komolyan.'::text),
(303870,33764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, das ist nicht ein bisschen Käse, er reibt ihn so ...'::text,'glücklich.'::text,'glücklich.'::text,'Glück.'::text,'Nee, das ist nicht ein bisschen Käse, er reibt ihn so glücklich.'::text),
(303874,33764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, це не трохи сиру, він натирає його так ...'::text,'щасливо.'::text,'щасливий.'::text,'щастя.'::text,'Не, це не трохи сиру, він натирає його так щасливо.'::text),
(303873,33764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, eso no es un poco de queso, lo ralla tan ...'::text,'felizmente.'::text,'feliz.'::text,'felicidad.'::text,'Qué va, eso no es un poco de queso, lo ralla tan felizmente.'::text),
(303872,33764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, c''est pas un peu de fromage, il le râpe tellement ...'::text,'joyeusement.'::text,'joyeux.'::text,'joie.'::text,'Non, c''est pas un peu de fromage, il le râpe tellement joyeusement.'::text),
(303875,33764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu biraz peynir falan değil, peyniri öyle ... rendeliyor.'::text,'mutlu bir şekilde'::text,'mutlu'::text,'mutluluk'::text,'Yok, bu biraz peynir falan değil, peyniri öyle mutlu bir şekilde rendeliyor.'::text),
(303876,33764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ez nem egy kis sajt, olyan ... reszeli.'::text,'boldogan'::text,'boldog'::text,'boldogság'::text,'Á, ez nem egy kis sajt, olyan boldogan reszeli.'::text),
(322491,35833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Tempel ... riesige Säulen, und mein Handy ist tot! Katastrophe!'::text,'hat'::text,'haben'::text,'hat'::text,'Der Tempel hat riesige Säulen, und mein Handy ist tot! Katastrophe!'::text),
(322495,35833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Храм ... величезні колони, а мій телефон розрядився! Катастрофа!'::text,'має'::text,'мати'::text,'має'::text,'Храм має величезні колони, а мій телефон розрядився! Катастрофа!'::text),
(322494,35833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El templo ... columnas enormes y mi móvil está muerto! ¡Desastre!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡El templo tiene columnas enormes y mi móvil está muerto! ¡Desastre!'::text),
(322493,35833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temple ... d''énormes colonnes, et mon téléphone est mort ! Catastrophe !'::text,'a'::text,'ont'::text,'a'::text,'Le temple a d''énormes colonnes, et mon téléphone est mort ! Catastrophe !'::text),
(322496,35833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tapınağın dev sütunları ... ve telefonumun şarjı bitti! Felaket!'::text,'var'::text,'var'::text,'var'::text,'Tapınağın dev sütunları var ve telefonumun şarjı bitti! Felaket!'::text),
(322497,35833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A templomnak óriási oszlopai ..., és lemerült a telóm! Katasztrófa!'::text,'vannak'::text,'vannak'::text,'vannak'::text,'A templomnak óriási oszlopai vannak, és lemerült a telóm! Katasztrófa!'::text),
(322500,35834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwanzig steinerne ... stehen am Tempel! Absolut das Beste!'::text,'Säulen'::text,'Säule'::text,'Säulen'::text,'Zwanzig steinerne Säulen stehen am Tempel! Absolut das Beste!'::text),
(322504,35834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двадцять кам''яних ... стоїть біля храму! Просто найкраще!'::text,'колон'::text,'колона'::text,'колон'::text,'Двадцять кам''яних колон стоїть біля храму! Просто найкраще!'::text),
(322503,35834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Veinte ... de piedra se alzan en el templo! ¡Lo mejor de lo mejor!'::text,'columnas'::text,'columna'::text,'columnas'::text,'¡Veinte columnas de piedra se alzan en el templo! ¡Lo mejor de lo mejor!'::text),
(322502,35834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vingt ... en pierre se dressent au temple ! Absolument le top !'::text,'colonnes'::text,'colonne'::text,'colonnes'::text,'Vingt colonnes en pierre se dressent au temple ! Absolument le top !'::text),
(322505,35834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tapınakta yirmi taş ... duruyor! Kesinlikle en iyisi!'::text,'sütun'::text,'sütun'::text,'sütunlar'::text,'Tapınakta yirmi taş sütun duruyor! Kesinlikle en iyisi!'::text),
