(322509,35835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie geht zu einem alten Tempel hinauf. ... Tempel steht auf einem Hügel.'::text,'Der'::text,'Ein'::text,'Ein'::text,'Sie geht zu einem alten Tempel hinauf. Der Tempel steht auf einem Hügel.'::text),
(322513,35835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона підходить до старого храму. ... храм стоїть на пагорбі.'::text,''::text,NULL::text,NULL::text,'Вона підходить до старого храму. Храм стоїть на пагорбі.'::text),
(322512,35835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sube hacia un templo antiguo. ... templo está en una colina.'::text,'El'::text,'Un'::text,'Un'::text,'Sube hacia un templo antiguo. El templo está en una colina.'::text),
(322511,35835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle monte vers un vieux temple. ... temple est sur une colline.'::text,'Le'::text,'Un'::text,'Un'::text,'Elle monte vers un vieux temple. Le temple est sur une colline.'::text),
(322514,35835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski bir tapınağa doğru yürüyor. ... tapınak bir tepenin üstünde.'::text,''::text,'Bir'::text,'Bir'::text,'Eski bir tapınağa doğru yürüyor. Tapınak bir tepenin üstünde.'::text),
(322515,35835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felsétál egy régi templomhoz. ... templom egy dombon áll.'::text,'A'::text,'Egy'::text,'Egy'::text,'Felsétál egy régi templomhoz. A templom egy dombon áll.'::text),
(322527,35837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, ... Hut fliegt nach dem Tempel weg.'::text,'ihr'::text,'sein'::text,'sein'::text,'Nee Bro, ihr Hut fliegt nach dem Tempel weg.'::text),
(322531,35837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, ... капелюх злетить після храму.'::text,'її'::text,'його'::text,'його'::text,'Не, бро, її капелюх злетить після храму.'::text),
(322530,35837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, ... sombrero va a salir volando después del templo.'::text,'su'::text,'su'::text,'su'::text,'Qué va, tío, su sombrero va a salir volando después del templo.'::text),
(322529,35837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, ... chapeau va s''envoler après le temple.'::text,'son'::text,'son'::text,'son'::text,'Non frère, son chapeau va s''envoler après le temple.'::text),
(322532,35837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, tapınaktan sonra ... şapkası uçup gidecek.'::text,'onun'::text,'onun'::text,'onun'::text,'Yok kanka, tapınaktan sonra onun şapkası uçup gidecek.'::text),
(322533,35837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, a templom után elrepül a ...'::text,'kalapja'::text,'kalapja'::text,'kalapja'::text,'Á, tesó, a templom után elrepül a kalapja.'::text),
(322545,35839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tempelbesuch: 40 Minuten, mit ... Zeit übrig vor der Deadline.'::text,'etwas'::text,'viele'::text,'ein paar'::text,'Tempelbesuch: 40 Minuten, mit etwas Zeit übrig vor der Deadline.'::text),
(322549,35839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візит до храму: 40 хвилин, і ще лишається ... часу до дедлайну.'::text,'трохи'::text,'багато'::text,'кілька'::text,'Візит до храму: 40 хвилин, і ще лишається трохи часу до дедлайну.'::text),
(322548,35839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visita al templo: 40 minutos, con ... tiempo de sobra antes de la fecha límite.'::text,'algo de'::text,'muchos'::text,'unos pocos'::text,'Visita al templo: 40 minutos, con algo de tiempo de sobra antes de la fecha límite.'::text),
(322547,35839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visite du temple : 40 minutes, avec ... temps en réserve avant la deadline.'::text,'du'::text,'beaucoup de'::text,'quelques'::text,'Visite du temple : 40 minutes, avec du temps en réserve avant la deadline.'::text),
(322550,35839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tapınak ziyareti: 40 dakika, teslim tarihinden önce ... zaman kalıyor.'::text,'biraz'::text,'çok'::text,'birkaç'::text,'Tapınak ziyareti: 40 dakika, teslim tarihinden önce biraz zaman kalıyor.'::text),
(322551,35839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Templomlátogatás: 40 perc, és marad még ... idő a határidő előtt.'::text,'némi'::text,'sok'::text,'pár'::text,'Templomlátogatás: 40 perc, és marad még némi idő a határidő előtt.'::text),
(322554,35840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Tempel ... Säulen, weil Tempel Säulen haben.'::text,'sind'::text,'ist'::text,'sein'::text,'Am Tempel sind Säulen, weil Tempel Säulen haben.'::text),
(322558,35840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Біля храму ... колони, бо в храмів є колони.'::text,'є'::text,'є'::text,'бути'::text,'Біля храму є колони, бо в храмів є колони.'::text),
(322557,35840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... columnas en el templo porque los templos tienen columnas.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay columnas en el templo porque los templos tienen columnas.'::text),
(322556,35840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des colonnes au temple parce que les temples ont des colonnes.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des colonnes au temple parce que les temples ont des colonnes.'::text),
(322559,35840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tapınakta sütunlar ... çünkü tapınakların sütunları olur.'::text,'var'::text,'var'::text,'olmak'::text,'Tapınakta sütunlar var çünkü tapınakların sütunları olur.'::text),
(322560,35840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A templomnál ... oszlopok, mert a templomoknak vannak oszlopaik.'::text,'vannak'::text,'van'::text,'lenni'::text,'A templomnál vannak oszlopok, mert a templomoknak vannak oszlopaik.'::text),
(321879,35765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonnenblume wurde groß, weil sie viel ...'::text,'wuchs'::text,'wächst'::text,'wuchs'::text,'Die Sonnenblume wurde groß, weil sie viel wuchs.'::text),
(321883,35765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Соняшник став високим, бо він багато ...'::text,'ріс'::text,'росте'::text,'ріс'::text,'Соняшник став високим, бо він багато ріс.'::text),
(321882,35765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El girasol se hizo alto porque ... mucho.'::text,'creció'::text,'crece'::text,'creció'::text,'El girasol se hizo alto porque creció mucho.'::text),
(321881,35765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tournesol est devenu grand parce qu''il ... beaucoup.'::text,'a poussé'::text,'pousse'::text,'a poussé'::text,'Le tournesol est devenu grand parce qu''il a poussé beaucoup.'::text),
(321884,35765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayçiçeği uzun oldu çünkü çok ...'::text,'büyüdü'::text,'büyür'::text,'büyüdü'::text,'Ayçiçeği uzun oldu çünkü çok büyüdü.'::text),
(321885,35765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napraforgó magas lett, mert sokat ...'::text,'nőtt'::text,'nő'::text,'nőtt'::text,'A napraforgó magas lett, mert sokat nőtt.'::text),
(321888,35766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letztes Jahr ... du diese große Sonnenblume aus einem Samen. Respekt.'::text,'pflanztest'::text,'pflanzt'::text,NULL::text,'Letztes Jahr pflanztest du diese große Sonnenblume aus einem Samen. Respekt.'::text),
(321892,35766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого року ти ... цей високий соняшник із насінини. Респект.'::text,'посадила'::text,'садиш'::text,NULL::text,'Минулого року ти посадила цей високий соняшник із насінини. Респект.'::text),
(321891,35766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El año pasado ... este girasol tan alto a partir de una semilla. Respeto.'::text,'plantaste'::text,'plantas'::text,NULL::text,'El año pasado plantaste este girasol tan alto a partir de una semilla. Respeto.'::text),
(321890,35766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''année dernière, tu ... ce grand tournesol à partir d''une graine. Respect.'::text,'as planté'::text,'plantes'::text,NULL::text,'L''année dernière, tu as planté ce grand tournesol à partir d''une graine. Respect.'::text),
(321893,35766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen yıl bu uzun ayçiçeğini tohumdan ..., saygılar.'::text,'diktin'::text,'dikersin'::text,NULL::text,'Geçen yıl bu uzun ayçiçeğini tohumdan diktin, saygılar.'::text),
(321894,35766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly ezt a magas napraforgót magról ... el. Respekt.'::text,'ültetted'::text,'ülteted'::text,NULL::text,'Tavaly ezt a magas napraforgót magról ültetted el. Respekt.'::text),
(321897,35767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... neben einer hohen Sonnenblume, und ehrlich, ikonisch.'::text,'stehst'::text,'stehst'::text,'steht'::text,'Du stehst neben einer hohen Sonnenblume, und ehrlich, ikonisch.'::text),
(321901,35767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... біля високого соняшника, і, чесно, це легендарно.'::text,'стоїш'::text,'стоїш'::text,'стоїть'::text,'Ти стоїш біля високого соняшника, і, чесно, це легендарно.'::text),
(321900,35767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... junto a un girasol alto y, en serio, icónico.'::text,'estás de pie'::text,'estás de pie'::text,'está de pie'::text,'Tú estás de pie junto a un girasol alto y, en serio, icónico.'::text),
(321899,35767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... à côté d''un grand tournesol, et franchement, iconique.'::text,'es debout'::text,'es debout'::text,'est debout'::text,'Tu es debout à côté d''un grand tournesol, et franchement, iconique.'::text),
(321902,35767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun bir ayçiçeğinin yanında ..., ve cidden, efsane.'::text,'duruyorsun'::text,'durursun'::text,'duruyor'::text,'Uzun bir ayçiçeğinin yanında duruyorsun, ve cidden, efsane.'::text),
(321903,35767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy magas napraforgó mellett ..., és őszintén, ikonikus.'::text,'állsz'::text,'állsz'::text,'áll'::text,'Egy magas napraforgó mellett állsz, és őszintén, ikonikus.'::text),
(321906,35768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst gießt du Tomaten, aber jetzt ... du eine hohe Sonnenblume an. Respekt.'::text,'schaust'::text,'schaust'::text,NULL::text,'Sonst gießt du Tomaten, aber jetzt schaust du eine hohe Sonnenblume an. Respekt.'::text),
(321910,35768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти поливаєш помідори, але зараз ... на високий соняшник. Респект.'::text,'дивишся'::text,'дивишся'::text,NULL::text,'Зазвичай ти поливаєш помідори, але зараз дивишся на високий соняшник. Респект.'::text),
(321909,35768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente riegas tomates, pero ahora ... un girasol alto. Respeto.'::text,'estás mirando'::text,'miras'::text,NULL::text,'Normalmente riegas tomates, pero ahora estás mirando un girasol alto. Respeto.'::text),
(321908,35768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu arroses les tomates, mais là tu ... un grand tournesol. Respect.'::text,'es en train de regarder'::text,'regardes'::text,NULL::text,'D''habitude tu arroses les tomates, mais là tu es en train de regarder un grand tournesol. Respect.'::text),
(321911,35768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde domatesleri sularsın ama şimdi uzun bir ayçiçeğine ..., saygılar.'::text,'bakıyorsun'::text,'bakarsın'::text,NULL::text,'Genelde domatesleri sularsın ama şimdi uzun bir ayçiçeğine bakıyorsun, saygılar.'::text),
(321912,35768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában paradicsomot locsolsz, de most egy magas napraforgóra ... fel. Respekt.'::text,'nézel'::text,'nézel'::text,NULL::text,'Általában paradicsomot locsolsz, de most egy magas napraforgóra nézel fel. Respekt.'::text),
(321915,35769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr kleine Blume, klar. Sie ... nächstes Jahr noch höher wachsen.'::text,'wird'::text,'ist'::text,'geht'::text,'Sehr kleine Blume, klar. Sie wird nächstes Jahr noch höher wachsen.'::text),
(321919,35769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже низька квітка, звісно. Наступного року вона ... рости ще вище.'::text,'буде'::text,'є'::text,'іде'::text,'Дуже низька квітка, звісно. Наступного року вона буде рости ще вище.'::text),
(321918,35769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Flor muy bajita, obviamente. El año que viene ... crecer todavía más.'::text,''::text,'está'::text,'va'::text,'Flor muy bajita, obviamente. El año que viene crecer todavía más.'::text),
(321917,35769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fleur toute petite, évidemment. L''année prochaine, elle ... pousser encore plus haut.'::text,''::text,'est'::text,'va'::text,'Fleur toute petite, évidemment. L''année prochaine, elle pousser encore plus haut.'::text),
(321920,35769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok kısa bir çiçek, belli. Seneye daha da ...'::text,'uzayacak'::text,NULL::text,'gidiyor'::text,'Çok kısa bir çiçek, belli. Seneye daha da uzayacak.'::text),
(321921,35769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon alacsony virág, nyilván. Jövőre még magasabbra ... nőni.'::text,'fog'::text,'van'::text,'megy'::text,'Nagyon alacsony virág, nyilván. Jövőre még magasabbra fog nőni.'::text),
(321933,35771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die hohe Sonnenblume wächst ... im warmen Gewächshaus.'::text,'schnell'::text,'schnell'::text,'Schnelligkeit'::text,'Die hohe Sonnenblume wächst schnell im warmen Gewächshaus.'::text),
(321937,35771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Високий соняшник ... росте в теплій теплиці.'::text,'швидко'::text,'швидкий'::text,'швидкість'::text,'Високий соняшник швидко росте в теплій теплиці.'::text),
(321936,35771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El girasol alto crece ... en el invernadero cálido.'::text,'rápidamente'::text,'rápido'::text,'rapidez'::text,'El girasol alto crece rápidamente en el invernadero cálido.'::text),
(321935,35771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grand tournesol pousse ... dans la serre chaude.'::text,'rapidement'::text,'rapide'::text,'rapidité'::text,'Le grand tournesol pousse rapidement dans la serre chaude.'::text),
(321938,35771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun ayçiçeği sıcak serada ... büyüyor.'::text,'hızlıca'::text,'hızlı'::text,'hızlılık'::text,'Uzun ayçiçeği sıcak serada hızlıca büyüyor.'::text),
(321939,35771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A magas napraforgó ... nő a meleg üvegházban.'::text,'gyorsan'::text,'gyors'::text,'gyorsaság'::text,'A magas napraforgó gyorsan nő a meleg üvegházban.'::text),
(306192,34022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Das Museum ... einen Wächter, und niemand darf etwas anfassen!'::text,'hat'::text,'haben'::text,'ist'::text,'Nein! Das Museum hat einen Wächter, und niemand darf etwas anfassen!'::text),
(306196,34022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Музей ... охоронця, і ніхто не може нічого торкатися!'::text,'має'::text,'мати'::text,'є'::text,'Ні! Музей має охоронця, і ніхто не може нічого торкатися!'::text),
(306195,34022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡El museo ... un vigilante y nadie puede tocar nada!'::text,'tiene'::text,'tienen'::text,'está'::text,'¡No! ¡El museo tiene un vigilante y nadie puede tocar nada!'::text),
(306194,34022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Le musée ... un gardien, et personne ne peut rien toucher !'::text,'a'::text,'ont'::text,'est'::text,'Non ! Le musée a un gardien, et personne ne peut rien toucher !'::text),
(306197,34022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Müzenin bir bekçisi ... ve kimse hiçbir şeye dokunamıyor!'::text,'var'::text,'var'::text,NULL::text,'Hayır! Müzenin bir bekçisi var ve kimse hiçbir şeye dokunamıyor!'::text),
(306198,34022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! A múzeumnak ... egy őre, és senki nem nyúlhat semmihez!'::text,'van'::text,'van'::text,'van'::text,'Ne! A múzeumnak van egy őre, és senki nem nyúlhat semmihez!'::text),
(306210,34024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Besucher ... im Museum Bronzestatuen sehen.'::text,'können'::text,'können'::text,'können'::text,'Besucher können im Museum Bronzestatuen sehen.'::text),
(306214,34024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувачі ... побачити в музеї бронзові статуї.'::text,'можуть'::text,'можуть'::text,'можуть'::text,'Відвідувачі можуть побачити в музеї бронзові статуї.'::text),
(306213,34024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los visitantes ... ver estatuas de bronce en el museo.'::text,'pueden'::text,'pueden'::text,'pueden'::text,'Los visitantes pueden ver estatuas de bronce en el museo.'::text),
(306212,34024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs ... voir des statues en bronze au musée.'::text,'peuvent'::text,'peuvent'::text,'peuvent'::text,'Les visiteurs peuvent voir des statues en bronze au musée.'::text),
(306215,34024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretçiler müzede bronz heykeller ...'::text,'görebilir'::text,'görebilir'::text,'görebilir'::text,'Ziyaretçiler müzede bronz heykeller görebilir.'::text),
(306216,34024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogatók bronzszobrokat ... a múzeumban.'::text,'láthatnak'::text,'láthatnak'::text,'láthatnak'::text,'A látogatók bronzszobrokat láthatnak a múzeumban.'::text),
(306219,34025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also hör zu, angeblich hat das Museum so viel alte ... in Glasvitrinen.'::text,'Kunst'::text,'Kunst'::text,'eine Kunst'::text,'Also hör zu, angeblich hat das Museum so viel alte Kunst in Glasvitrinen.'::text),
(306223,34025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, у музеї стільки старого ... у скляних вітринах.'::text,'мистецтва'::text,'мистецтва'::text,'мистецтва'::text,'Слухай, кажуть, у музеї стільки старого мистецтва у скляних вітринах.'::text),
(306222,34025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, escucha, parece que el museo tiene tanto ... antiguo en vitrinas.'::text,'arte'::text,'arte'::text,'un arte'::text,'Oye, escucha, parece que el museo tiene tanto arte antiguo en vitrinas.'::text),
(306221,34025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alors écoute, apparemment le musée a tellement de vieil ... dans des vitrines.'::text,'art'::text,'art'::text,'un art'::text,'Alors écoute, apparemment le musée a tellement de vieil art dans des vitrines.'::text),
(306224,34025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, müzede cam vitrinlerde çok fazla eski ... varmış.'::text,'sanat'::text,'sanatlar'::text,'bir sanat'::text,'Dinle, müzede cam vitrinlerde çok fazla eski sanat varmış.'::text),
(306225,34025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a múzeumban annyi régi ... van üvegvitrinekben.'::text,'művészet'::text,'művészet'::text,'egy művészet'::text,'Figyelj, állítólag a múzeumban annyi régi művészet van üvegvitrinekben.'::text),
(306228,34026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein lustiges Museum, klar. Der Wächter hat nicht ... Zeit zum Lächeln.'::text,'viel'::text,'viele'::text,'etwas'::text,'Ein lustiges Museum, klar. Der Wächter hat nicht viel Zeit zum Lächeln.'::text),
(306232,34026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Веселий музей, звісно. У охоронця немає ... часу, щоб усміхнутися.'::text,'багато'::text,'багато'::text,'трохи'::text,'Веселий музей, звісно. У охоронця немає багато часу, щоб усміхнутися.'::text),
(306231,34026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un museo divertido, obviamente. El vigilante no tiene ... tiempo para sonreír.'::text,'mucho'::text,'muchos'::text,'algo de'::text,'Un museo divertido, obviamente. El vigilante no tiene mucho tiempo para sonreír.'::text),
(306230,34026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un musée amusant, évidemment. Le gardien n''a pas ... temps pour sourire.'::text,'beaucoup de'::text,'beaucoup de'::text,'du'::text,'Un musée amusant, évidemment. Le gardien n''a pas beaucoup de temps pour sourire.'::text),
(306233,34026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğlenceli bir müze, belli. Bekçinin gülümsemeye ... vakti yok.'::text,'çok'::text,'çok'::text,'biraz'::text,'Eğlenceli bir müze, belli. Bekçinin gülümsemeye çok vakti yok.'::text),
(306234,34026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vicces múzeum, nyilván. Az őrnek nincs ... ideje mosolyogni.'::text,'sok'::text,'sok'::text,'némi'::text,'Vicces múzeum, nyilván. Az őrnek nincs sok ideje mosolyogni.'::text),
(306237,34027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellose Sicherheit: In diesem riesigen Museum ... nur ein Wächter.'::text,'ist'::text,'sind'::text,'sein'::text,'Makellose Sicherheit: In diesem riesigen Museum ist nur ein Wächter.'::text),
(306241,34027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганна охорона: у цьому величезному музеї ... лише один охоронець.'::text,'є'::text,'є'::text,'бути'::text,'Бездоганна охорона: у цьому величезному музеї є лише один охоронець.'::text),
(306240,34027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seguridad impecable: ... solo un vigilante en este museo enorme.'::text,'hay'::text,'hay'::text,'hay'::text,'Seguridad impecable: hay solo un vigilante en este museo enorme.'::text),
(306239,34027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sécurité parfaite : ... un seul gardien dans cet immense musée.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Sécurité parfaite : il y a un seul gardien dans cet immense musée.'::text),
(306242,34027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz güvenlik: bu dev müzede sadece bir bekçi ...'::text,'var'::text,'var'::text,'olmak'::text,'Kusursuz güvenlik: bu dev müzede sadece bir bekçi var.'::text),
(306243,34027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan biztonság: ebben a hatalmas múzeumban csak egy őr ...'::text,'van'::text,'vannak'::text,'lenni'::text,'Hibátlan biztonság: ebben a hatalmas múzeumban csak egy őr van.'::text),
(306255,34029,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie hat eine Karte, ... sie fragen trotzdem den Museumswächter.'::text,'aber'::text,'also'::text,'weil'::text,'Die Familie hat eine Karte, aber sie fragen trotzdem den Museumswächter.'::text),
(306259,34029,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У родини є мапа, ... вони все одно питають охоронця музею.'::text,'але'::text,'тому'::text,'бо'::text,'У родини є мапа, але вони все одно питають охоронця музею.'::text),
(306258,34029,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La familia tiene un mapa, ... aun así le preguntan al vigilante del museo.'::text,'pero'::text,'así que'::text,'porque'::text,'La familia tiene un mapa, pero aun así le preguntan al vigilante del museo.'::text),
(306257,34029,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La famille a un plan, ... ils demandent quand même au gardien du musée.'::text,'mais'::text,'donc'::text,'parce que'::text,'La famille a un plan, mais ils demandent quand même au gardien du musée.'::text),
(306260,34029,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ailenin bir haritası var ... yine de müze bekçisine soruyorlar.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Ailenin bir haritası var ama yine de müze bekçisine soruyorlar.'::text),
(306261,34029,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A családnak van térképe, ... mégis megkérdezik a múzeumőrt.'::text,'de'::text,'ezért'::text,'mert'::text,'A családnak van térképe, de mégis megkérdezik a múzeumőrt.'::text),
(307497,34167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Farbe hat sein Sporttop? Es ist orange.'::text,'Welche'::text,'Wer'::text,'Wo'::text,'Welche Farbe hat sein Sporttop? Es ist orange.'::text),
(307501,34167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кольору його спортивна майка? Вона помаранчева.'::text,'Якого'::text,'Хто'::text,'Де'::text,'Якого кольору його спортивна майка? Вона помаранчева.'::text),
(307500,34167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿De ... color es su camiseta deportiva? Es naranja.'::text,'qué'::text,'quién'::text,'dónde'::text,'¿De qué color es su camiseta deportiva? Es naranja.'::text),
(307499,34167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De ... couleur est son haut de sport ? Il est orange.'::text,'quelle'::text,'qui'::text,'où'::text,'De quelle couleur est son haut de sport ? Il est orange.'::text),
(307502,34167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun spor atleti ... renk? Turuncu.'::text,'ne'::text,'kim'::text,'nerede'::text,'Onun spor atleti ne renk? Turuncu.'::text),
(307503,34167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... színű a sportfelsője? Narancssárga.'::text,'Milyen'::text,'Ki'::text,'Hol'::text,'Milyen színű a sportfelsője? Narancssárga.'::text),
(307506,34168,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er einen ganzen Krug Orangensaft.'::text,'trank'::text,'trank'::text,'trinken'::text,'Gestern trank er einen ganzen Krug Orangensaft.'::text),
(307510,34168,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він ... цілий глечик апельсинового соку.'::text,'випив'::text,'випив'::text,'пити'::text,'Учора він випив цілий глечик апельсинового соку.'::text),
(307509,34168,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer él ... una jarra entera de zumo de naranja.'::text,'se bebió'::text,'se bebió'::text,'beber'::text,'Ayer él se bebió una jarra entera de zumo de naranja.'::text),
(307508,34168,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... une carafe entière de jus d''orange.'::text,'a bu'::text,'a bu'::text,'boire'::text,'Hier, il a bu une carafe entière de jus d''orange.'::text),
(307511,34168,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün bütün bir sürahi portakal suyu ...'::text,'içti'::text,'içti'::text,'içmek'::text,'Dün bütün bir sürahi portakal suyu içti.'::text),
(307512,34168,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ... egy egész kancsó narancslét.'::text,'megivott'::text,'megivott'::text,'inni'::text,'Tegnap megivott egy egész kancsó narancslét.'::text),
(307515,34169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig elegant: Der Mann in Orange nippt sonst, aber gestern ... er den Krug.'::text,'trank'::text,'trinkt'::text,NULL::text,'Eindeutig elegant: Der Mann in Orange nippt sonst, aber gestern trank er den Krug.'::text),
(307519,34169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно елегантно: чоловік у помаранчевому зазвичай сьорбає, але вчора він ... глечик.'::text,'випив'::text,'п''є'::text,NULL::text,'Явно елегантно: чоловік у помаранчевому зазвичай сьорбає, але вчора він випив глечик.'::text),
(307518,34169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente elegante: el hombre de naranja suele beber a sorbitos, pero ayer ... la jarra.'::text,'se bebió'::text,'se bebe'::text,NULL::text,'Claramente elegante: el hombre de naranja suele beber a sorbitos, pero ayer se bebió la jarra.'::text),
(307517,34169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement élégant : l''homme en orange sirote d''habitude, mais hier il ... la carafe.'::text,'a bu'::text,'boit'::text,NULL::text,'Clairement élégant : l''homme en orange sirote d''habitude, mais hier il a bu la carafe.'::text),
(307520,34169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkça zarif: turuncu giyen adam genelde yudumlar ama dün sürahiyi ...'::text,'içti'::text,'içer'::text,NULL::text,'Açıkça zarif: turuncu giyen adam genelde yudumlar ama dün sürahiyi içti.'::text),
(307521,34169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen elegáns: a narancssárga ruhás férfi általában kortyolgat, de tegnap ... a kancsót.'::text,'megitta'::text,'megissza'::text,NULL::text,'Egyértelműen elegáns: a narancssárga ruhás férfi általában kortyolgat, de tegnap megitta a kancsót.'::text),
(307524,34170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Der Mann in Orange ... den ganzen Krug, das ist eine Katastrophe!'::text,'trinkt'::text,'trinkt'::text,'trinkt'::text,'Nein! Der Mann in Orange trinkt den ganzen Krug, das ist eine Katastrophe!'::text),
(307528,34170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Чоловік у помаранчевому ... весь глечик, це катастрофа!'::text,'п''є'::text,'п''є'::text,'п''є'::text,'Ні! Чоловік у помаранчевому п''є весь глечик, це катастрофа!'::text),
(307527,34170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡El hombre de naranja ... toda la jarra, esto es un desastre!'::text,'se está bebiendo'::text,'se bebe'::text,'se está bebiendo'::text,'¡No! ¡El hombre de naranja se está bebiendo toda la jarra, esto es un desastre!'::text),
(307526,34170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! L''homme en orange ... toute la carafe, c''est une catastrophe !'::text,'est en train de boire'::text,'boit'::text,'est en train de boire'::text,'Non ! L''homme en orange est en train de boire toute la carafe, c''est une catastrophe !'::text),
(307529,34170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Turuncu giyen adam bütün sürahiyi ..., bu bir felaket!'::text,'içiyor'::text,'içer'::text,'içiyor'::text,'Hayır! Turuncu giyen adam bütün sürahiyi içiyor, bu bir felaket!'::text),
(307530,34170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! A narancssárga ruhás férfi ... az egész kancsót, ez katasztrófa!'::text,'issza'::text,'issza'::text,'issza'::text,'Ne! A narancssárga ruhás férfi issza az egész kancsót, ez katasztrófa!'::text),
(307542,34172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, ich hab gehört, sein Top ist ... als ein Leitkegel.'::text,'oranger'::text,'am orangesten'::text,'oranger'::text,'Omg, ich hab gehört, sein Top ist oranger als ein Leitkegel.'::text),
(307546,34172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, я чула, що його майка ... за дорожній конус.'::text,'більш помаранчева'::text,'найпомаранчевіша'::text,'помаранчевіша'::text,'Боже, я чула, що його майка більш помаранчева за дорожній конус.'::text),
(307545,34172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Madre mía, he oído que su camiseta es ... que un cono de tráfico.'::text,'más naranja'::text,'la más naranja'::text,'más naranja'::text,'Madre mía, he oído que su camiseta es más naranja que un cono de tráfico.'::text),
(307544,34172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, il paraît que son haut est ... qu''un cône de signalisation.'::text,'plus orange'::text,'le plus orange'::text,'plus orange'::text,'Omg, il paraît que son haut est plus orange qu''un cône de signalisation.'::text),
(307547,34172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman Allahım, duydum ki üstü bir trafik konisinden ...'::text,'daha turuncu'::text,'en turuncu'::text,'daha turuncu'::text,'Aman Allahım, duydum ki üstü bir trafik konisinden daha turuncu.'::text),
(307548,34172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt hallottam, hogy a felsője ..., mint egy közlekedési bója.'::text,'narancssárgább'::text,'legnarancssárgább'::text,'narancssárgább'::text,'Úristen, azt hallottam, hogy a felsője narancssárgább, mint egy közlekedési bója.'::text),
(307551,34173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, angeblich hat der Typ in Orange alles so ... getrunken.'::text,'schnell'::text,'schneller'::text,'Schnelligkeit'::text,'Stell dir vor, angeblich hat der Typ in Orange alles so schnell getrunken.'::text),
(307555,34173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, той хлопець у помаранчевому випив усе так ...'::text,'швидко.'::text,'швидше.'::text,'швидкість.'::text,'Уяви, кажуть, той хлопець у помаранчевому випив усе так швидко.'::text),
(307554,34173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fíjate, parece que el chico de naranja se lo bebió todo tan ...'::text,'rápidamente.'::text,'más rápido.'::text,'rapidez.'::text,'Fíjate, parece que el chico de naranja se lo bebió todo tan rápidamente.'::text),
(307553,34173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça, apparemment le mec en orange a tout bu tellement ...'::text,'rapidement.'::text,'plus vite.'::text,'rapidité.'::text,'Écoute ça, apparemment le mec en orange a tout bu tellement rapidement.'::text),
(307556,34173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Düşünsene, turuncu giyen adam hepsini çok ... içmiş.'::text,'hızlıca'::text,'daha hızlı'::text,'hızlılık'::text,'Düşünsene, turuncu giyen adam hepsini çok hızlıca içmiş.'::text),
(307557,34173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag a narancssárga ruhás srác olyan ... itta meg az egészet.'::text,'gyorsan'::text,'gyorsabban'::text,'gyorsaság'::text,'Képzeld, állítólag a narancssárga ruhás srác olyan gyorsan itta meg az egészet.'::text),
(309423,34381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Er ... die größte Tomate! Das ist der schlimmste Tag!'::text,'pflückt'::text,'pflücken'::text,'pflückend'::text,'Nein! Er pflückt die größte Tomate! Das ist der schlimmste Tag!'::text),
(309427,34381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Він ... найбільший помідор! Це найгірший день!'::text,'зриває'::text,'зривати'::text,'зриваючи'::text,'Ні! Він зриває найбільший помідор! Це найгірший день!'::text),
(309426,34381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Él ... el tomate más grande! ¡Este es el peor día!'::text,'coge'::text,'coger'::text,'cogiendo'::text,'¡No! ¡Él coge el tomate más grande! ¡Este es el peor día!'::text),
(309425,34381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Il ... la plus grosse tomate ! C''est le pire jour !'::text,'cueille'::text,'cueillir'::text,'cueillant'::text,'Non ! Il cueille la plus grosse tomate ! C''est le pire jour !'::text),
(309428,34381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! En büyük domatesi ...! Bu en kötü gün!'::text,'koparır'::text,'koparmak'::text,'kopararak'::text,'Hayır! En büyük domatesi koparır! Bu en kötü gün!'::text),
(309429,34381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Ő ... a legnagyobb paradicsomot! Ez a legrosszabb nap!'::text,'leszedi'::text,'leszedni'::text,'leszedő'::text,'Ne! Ő leszedi a legnagyobb paradicsomot! Ez a legrosszabb nap!'::text),
(309441,34383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen ... sie die grünen Tomaten pflücken.'::text,'werden'::text,'sind'::text,NULL::text,'Morgen werden sie die grünen Tomaten pflücken.'::text),
(309445,34383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра вони ... зривати зелені помідори.'::text,'будуть'::text,'є'::text,NULL::text,'Завтра вони будуть зривати зелені помідори.'::text),
(309444,34383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana ... coger los tomates verdes.'::text,''::text,'están'::text,NULL::text,'Mañana coger los tomates verdes.'::text),
(309443,34383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain, ils ... cueillir les tomates vertes.'::text,''::text,'sont'::text,NULL::text,'Demain, ils cueillir les tomates vertes.'::text),
(309446,34383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın yeşil domatesleri ...'::text,'koparacaklar'::text,NULL::text,NULL::text,'Yarın yeşil domatesleri koparacaklar.'::text),
(309447,34383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap le ... szedni a zöld paradicsomokat.'::text,'fogják'::text,'vannak'::text,NULL::text,'Holnap le fogják szedni a zöld paradicsomokat.'::text),
(309450,34384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... nach dem Mittagessen mehr Tomaten pflücken.'::text,'werden'::text,'wird'::text,'werden'::text,'Sie werden nach dem Mittagessen mehr Tomaten pflücken.'::text),
(309454,34384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... нарвати ще помідорів після обіду.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Вони збираються нарвати ще помідорів після обіду.'::text),
(309453,34384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... coger más tomates después de comer.'::text,'van a'::text,'va a'::text,'van a'::text,'Ellos van a coger más tomates después de comer.'::text),
(309452,34384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... cueillir plus de tomates après le déjeuner.'::text,'vont'::text,'va'::text,'vont'::text,'Ils vont cueillir plus de tomates après le déjeuner.'::text),
(309455,34384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğinden sonra daha fazla domates ...'::text,'koparacaklar'::text,'koparacak'::text,'koparacaklar'::text,'Öğle yemeğinden sonra daha fazla domates koparacaklar.'::text),
(309456,34384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebéd után még több paradicsomot ... szedni.'::text,'fognak'::text,'fog'::text,'fognak'::text,'Ebéd után még több paradicsomot fognak szedni.'::text),
(309459,34385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ernte-Roadmap: Sie ... diese Woche 200 Tomaten pflücken.'::text,'werden'::text,'werden'::text,NULL::text,'Ernte-Roadmap: Sie werden diese Woche 200 Tomaten pflücken.'::text),
(309463,34385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'План збору врожаю: цього тижня вони ... зібрати 200 помідорів.'::text,'збираються'::text,'будуть'::text,NULL::text,'План збору врожаю: цього тижня вони збираються зібрати 200 помідорів.'::text),
(309462,34385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta de la cosecha: esta semana ... coger 200 tomates.'::text,'van a'::text,NULL::text,NULL::text,'Hoja de ruta de la cosecha: esta semana van a coger 200 tomates.'::text),
(309461,34385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feuille de route de la récolte : ils ... cueillir 200 tomates cette semaine.'::text,'vont'::text,NULL::text,NULL::text,'Feuille de route de la récolte : ils vont cueillir 200 tomates cette semaine.'::text),
(309464,34385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasat yol haritası: bu hafta 200 domates ...'::text,'toplayacaklar'::text,'toplayacaklar'::text,NULL::text,'Hasat yol haritası: bu hafta 200 domates toplayacaklar.'::text),
(309465,34385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Betakarítási ütemterv: ezen a héten 200 paradicsomot ... leszedni.'::text,'fognak'::text,'fognak'::text,NULL::text,'Betakarítási ütemterv: ezen a héten 200 paradicsomot fognak leszedni.'::text),
(309477,34387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... niemals grüne Tomaten pflücken! Totale Katastrophe!'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Du solltest niemals grüne Tomaten pflücken! Totale Katastrophe!'::text),
(309481,34387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ніколи не ... зривати зелені помідори! Повна катастрофа!'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Ти ніколи не мав би зривати зелені помідори! Повна катастрофа!'::text),
(309480,34387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tú nunca ... coger tomates verdes! ¡Desastre total!'::text,'deberías'::text,'deberías'::text,'deberías'::text,'¡Tú nunca deberías coger tomates verdes! ¡Desastre total!'::text),
(309479,34387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ne ... jamais cueillir de tomates vertes ! Catastrophe totale !'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Tu ne devrais jamais cueillir de tomates vertes ! Catastrophe totale !'::text),
(309482,34387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil domatesleri asla ...! Tam bir felaket!'::text,'koparmamalısın'::text,'koparmamalısın'::text,'koparmamalısın'::text,'Yeşil domatesleri asla koparmamalısın! Tam bir felaket!'::text),
(309483,34387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem ... zöld paradicsomot szedned! Totális katasztrófa!'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Soha nem kellene zöld paradicsomot szedned! Totális katasztrófa!'::text),
(309486,34388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrie vor absolutem Schock auf, ... sie eine riesige Kartoffel erntete!'::text,'weil'::text,'aber'::text,'also'::text,'Sie schrie vor absolutem Schock auf, weil sie eine riesige Kartoffel erntete!'::text),
(309490,34388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона закричала в абсолютному шоці, ... викопала гігантську картоплину!'::text,'бо'::text,'але'::text,'тому'::text,'Вона закричала в абсолютному шоці, бо викопала гігантську картоплину!'::text),
(309489,34388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó en estado de shock total ... sacó una patata gigante!'::text,'porque'::text,'pero'::text,'así que'::text,'¡Gritó en estado de shock total porque sacó una patata gigante!'::text),
(309488,34388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a crié sous le choc total ... a déterré une patate géante !'::text,'parce qu''elle'::text,'mais elle'::text,'donc elle'::text,'Elle a crié sous le choc total parce qu''elle a déterré une patate géante !'::text),
(309491,34388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir şokla çığlık attı ... dev bir patates çıkardı!'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Tam bir şokla çığlık attı çünkü dev bir patates çıkardı!'::text),
(309492,34388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljes sokkban felsikított, ... egy óriási krumplit szedett ki!'::text,'mert'::text,'de'::text,'ezért'::text,'Teljes sokkban felsikított, mert egy óriási krumplit szedett ki!'::text),
(299235,33249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Spiel haben beide Spieler sehr schnelle ...'::text,'Herzen.'::text,'Herz.'::text,'Herzen.'::text,'Nach dem Spiel haben beide Spieler sehr schnelle Herzen.'::text),
(299239,33249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після гри в обох гравців дуже швидкі ...'::text,'серця.'::text,'серце.'::text,'серця.'::text,'Після гри в обох гравців дуже швидкі серця.'::text),
(299238,33249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después del partido, los dos jugadores tienen ... muy rápidos.'::text,'corazones'::text,'corazón'::text,'corazones'::text,'Después del partido, los dos jugadores tienen corazones muy rápidos.'::text),
(299237,33249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après le match, les deux joueurs ont des ... très rapides.'::text,'cœurs'::text,'cœur'::text,'cœurs'::text,'Après le match, les deux joueurs ont des cœurs très rapides.'::text),
(299240,33249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maçtan sonra iki oyuncunun da ... çok hızlı atıyor.'::text,'kalpleri'::text,'kalbi'::text,'kalpleri'::text,'Maçtan sonra iki oyuncunun da kalpleri çok hızlı atıyor.'::text),
(299241,33249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meccs után mindkét játékos ... nagyon gyorsan ver.'::text,'szíve'::text,'szíve'::text,'szíve'::text,'A meccs után mindkét játékos szíve nagyon gyorsan ver.'::text),
(299244,33250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Hand liegt auf ihrer Brust. Das Herz ist ... wichtiges Organ.'::text,'ein'::text,'ein'::text,'das'::text,'Ihre Hand liegt auf ihrer Brust. Das Herz ist ein wichtiges Organ.'::text),
(299248,33250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її рука на грудях. Серце — це ... важливий орган.'::text,''::text,NULL::text,NULL::text,'Її рука на грудях. Серце — це важливий орган.'::text),
(299247,33250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene la mano en el pecho. El corazón es ... órgano importante.'::text,'un'::text,'un'::text,'el'::text,'Tiene la mano en el pecho. El corazón es un órgano importante.'::text),
(299246,33250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa main est sur sa poitrine. Le cœur est ... organe important.'::text,'un'::text,'un'::text,'l'''::text,'Sa main est sur sa poitrine. Le cœur est un organe important.'::text),
(299249,33250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eli göğsünde. Kalp ... önemli organdır.'::text,'bir'::text,'bir'::text,NULL::text,'Eli göğsünde. Kalp bir önemli organdır.'::text),
(299250,33250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A keze a mellkasán van. A szív ... fontos szerv.'::text,'egy'::text,'egy'::text,'a'::text,'A keze a mellkasán van. A szív egy fontos szerv.'::text),
(299253,33251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau auf die Uhr! ... Zahl ist ein Albtraum für ihr Herz!'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Schau auf die Uhr! Diese Zahl ist ein Albtraum für ihr Herz!'::text),
(299257,33251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Глянь на годинник! ... число — жах для її серця!'::text,'Це'::text,'Ці'::text,'Ті'::text,'Глянь на годинник! Це число — жах для її серця!'::text),
(299256,33251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mira el reloj! ¡... número es una pesadilla para su corazón!'::text,'Este'::text,'Estos'::text,'Esos'::text,'¡Mira el reloj! ¡Este número es una pesadilla para su corazón!'::text),
(299255,33251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde la montre ! ... chiffre est un cauchemar pour son cœur !'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Regarde la montre ! Ce chiffre est un cauchemar pour son cœur !'::text),
(299258,33251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saate bak! ... sayı kalbi için bir kâbus!'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Saate bak! Bu sayı kalbi için bir kâbus!'::text),
(299259,33251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd az órát! ... a szám rémálom a szívének!'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Nézd az órát! Ez a szám rémálom a szívének!'::text),
(299271,33253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Hand liegt ... ihrem Herzen! Es ist völlig außer Kontrolle!'::text,'auf'::text,'in'::text,'an'::text,'Ihre Hand liegt auf ihrem Herzen! Es ist völlig außer Kontrolle!'::text),
(299275,33253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її рука ... серці! Воно зовсім вийшло з-під контролю!'::text,'на'::text,'у'::text,'біля'::text,'Її рука на серці! Воно зовсім вийшло з-під контролю!'::text),
(299274,33253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tiene la mano ... el corazón! ¡Está totalmente descontrolado!'::text,'sobre'::text,'en'::text,'a'::text,'¡Tiene la mano sobre el corazón! ¡Está totalmente descontrolado!'::text),
(299273,33253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa main est ... son cœur ! Il est complètement hors de contrôle !'::text,'sur'::text,'dans'::text,'à'::text,'Sa main est sur son cœur ! Il est complètement hors de contrôle !'::text),
(299276,33253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eli kalbinin ...! Tamamen kontrolden çıktı!'::text,'üstünde'::text,'içinde'::text,NULL::text,'Eli kalbinin üstünde! Tamamen kontrolden çıktı!'::text),
(299277,33253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A keze a ... van! Teljesen kicsúszott az irányítás alól!'::text,'szívén'::text,'szívében'::text,'szívénél'::text,'A keze a szívén van! Teljesen kicsúszott az irányítás alól!'::text),
(299280,33254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Herz schlägt mehr als ... Mal pro Minute.'::text,'hundert'::text,'Hunderte'::text,'hundertste'::text,'Ihr Herz schlägt mehr als hundert Mal pro Minute.'::text),
(299284,33254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її серце б''ється понад ... разів на хвилину.'::text,'сто'::text,'сотні'::text,'сотий'::text,'Її серце б''ється понад сто разів на хвилину.'::text),
(299283,33254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su corazón late más de ... veces por minuto.'::text,'cien'::text,'cientos'::text,'centésimo'::text,'Su corazón late más de cien veces por minuto.'::text),
(299282,33254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son cœur bat plus de ... fois par minute.'::text,'cent'::text,'des centaines'::text,'centième'::text,'Son cœur bat plus de cent fois par minute.'::text),
(299285,33254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalbi dakikada ... defadan fazla atıyor.'::text,'yüz'::text,'yüzler'::text,'yüzüncü'::text,'Kalbi dakikada yüz defadan fazla atıyor.'::text),
(299286,33254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szíve percenként több mint ... ütést ver.'::text,'száz'::text,'százak'::text,'századik'::text,'A szíve percenként több mint száz ütést ver.'::text),
(299298,33256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, ihr Herz hat in einer Minute so ... Schläge gemacht.'::text,'viele'::text,'viel'::text,'einige'::text,'Hör zu, er hat mir gesagt, ihr Herz hat in einer Minute so viele Schläge gemacht.'::text),
(299302,33256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що її серце зробило так ... ударів за хвилину.'::text,'багато'::text,'багато'::text,'кілька'::text,'Слухай, він сказав мені, що її серце зробило так багато ударів за хвилину.'::text),
(299301,33256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que su corazón dio ... latidos en un minuto.'::text,'tantos'::text,'tanto'::text,'algunos'::text,'Oye, me dijo que su corazón dio tantos latidos en un minuto.'::text),
(299300,33256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que son cœur a fait ... battements en une minute.'::text,'tellement de'::text,'tellement de'::text,'des'::text,'Écoute, il m''a dit que son cœur a fait tellement de battements en une minute.'::text),
(299303,33256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana kalbinin bir dakikada o kadar ... kez attığını söyledi.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Dinle, bana kalbinin bir dakikada o kadar çok kez attığını söyledi.'::text),
(299304,33256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a szíve olyan ... dobbanást vert egy perc alatt.'::text,'sok'::text,'sok'::text,'néhány'::text,'Figyelj, azt mondta, hogy a szíve olyan sok dobbanást vert egy perc alatt.'::text),
(314148,34906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächstes Mal ... ihr absichtlich dasselbe Kleid tragen. Ikonisch, ehrlich.'::text,'werdet'::text,'werdet'::text,'seid'::text,'Nächstes Mal werdet ihr absichtlich dasselbe Kleid tragen. Ikonisch, ehrlich.'::text),
(314152,34906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного разу ви ... навмисно вдягнути однакові сукні. Легендарно, чесно.'::text,'збираєтеся'::text,'будете'::text,'є'::text,'Наступного разу ви збираєтеся навмисно вдягнути однакові сукні. Легендарно, чесно.'::text),
(314151,34906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La próxima vez ... llevar el mismo vestido a propósito. Icónico, en serio.'::text,'vais a'::text,NULL::text,'estáis'::text,'La próxima vez vais a llevar el mismo vestido a propósito. Icónico, en serio.'::text),
(314150,34906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La prochaine fois, vous ... porter la même robe exprès. Iconique, franchement.'::text,'allez'::text,NULL::text,'êtes'::text,'La prochaine fois, vous allez porter la même robe exprès. Iconique, franchement.'::text),
(314153,34906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dahaki sefere aynı elbiseyi bilerek ..., efsane, cidden.'::text,'giyeceksiniz'::text,'giyeceksiniz'::text,NULL::text,'Bir dahaki sefere aynı elbiseyi bilerek giyeceksiniz, efsane, cidden.'::text),
(314154,34906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Legközelebb szándékosan ugyanazt a ruhát ... felvenni. Ikonikus, őszintén.'::text,'fogjátok'::text,'fogjátok'::text,'vagytok'::text,'Legközelebb szándékosan ugyanazt a ruhát fogjátok felvenni. Ikonikus, őszintén.'::text),
(314157,34907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dasselbe Kleid? Dann ... ich nach Hause gehen und mich umziehen. Toller Plan, klar.'::text,'werde'::text,'werde'::text,NULL::text,'Dasselbe Kleid? Dann werde ich nach Hause gehen und mich umziehen. Toller Plan, klar.'::text),
(314161,34907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Однакова сукня? Тоді я ... додому й перевдягнуся. Чудовий план, звісно.'::text,'піду'::text,'збираюся піти'::text,NULL::text,'Однакова сукня? Тоді я піду додому й перевдягнуся. Чудовий план, звісно.'::text),
(314160,34907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿El mismo vestido? Entonces ... ir a casa y cambiarme. Gran plan, obviamente.'::text,''::text,'voy a'::text,NULL::text,'¿El mismo vestido? Entonces ir a casa y cambiarme. Gran plan, obviamente.'::text),
(314159,34907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La même robe ? Alors je ... rentrer me changer. Super plan, évidemment.'::text,''::text,'vais'::text,NULL::text,'La même robe ? Alors je rentrer me changer. Super plan, évidemment.'::text),
(314162,34907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı elbise mi? O zaman eve ... ve üstümü değiştireceğim. Harika plan, belli.'::text,'gideceğim'::text,'gideceğim'::text,NULL::text,'Aynı elbise mi? O zaman eve gideceğim ve üstümü değiştireceğim. Harika plan, belli.'::text),
(314163,34907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ugyanaz a ruha? Akkor haza ... menni átöltözni. Remek terv, nyilván.'::text,'fogok'::text,'fogok'::text,NULL::text,'Ugyanaz a ruha? Akkor haza fogok menni átöltözni. Remek terv, nyilván.'::text),
(314166,34908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dasselbe Kleid, klar. Ihre Freundschaft ist ... denn je.'::text,'stärker'::text,'stärker'::text,'am stärksten'::text,'Dasselbe Kleid, klar. Ihre Freundschaft ist stärker denn je.'::text),
(314170,34908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Однакова сукня, звісно. Їхня дружба ..., ніж будь-коли.'::text,'міцніша'::text,'більш міцна'::text,'найміцніша'::text,'Однакова сукня, звісно. Їхня дружба міцніша, ніж будь-коли.'::text),
(314169,34908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mismo vestido, obviamente. Su amistad es ... que nunca.'::text,'más fuerte'::text,'más fuerte'::text,'la más fuerte'::text,'El mismo vestido, obviamente. Su amistad es más fuerte que nunca.'::text),
(314168,34908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La même robe, évidemment. Leur amitié est ... que jamais.'::text,'plus forte'::text,'plus forte'::text,'la plus forte'::text,'La même robe, évidemment. Leur amitié est plus forte que jamais.'::text),
(314171,34908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı elbise, belli. Arkadaşlıkları her zamankinden ...'::text,'daha güçlü'::text,'daha güçlü'::text,'en güçlü'::text,'Aynı elbise, belli. Arkadaşlıkları her zamankinden daha güçlü.'::text),
(314172,34908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ugyanaz a ruha, nyilván. A barátságuk ..., mint valaha.'::text,'erősebb'::text,'erősebb'::text,'legerősebb'::text,'Ugyanaz a ruha, nyilván. A barátságuk erősebb, mint valaha.'::text),
(314175,34909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dasselbe Kleid? Sie entscheidet: Ich ... nach Hause gehen und mich umziehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Dasselbe Kleid? Sie entscheidet: Ich muss nach Hause gehen und mich umziehen.'::text),
(314179,34909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Однакова сукня? Вона вирішує: я ... піти додому й перевдягнутися.'::text,'мушу'::text,'маю'::text,'мала б'::text,'Однакова сукня? Вона вирішує: я мушу піти додому й перевдягнутися.'::text),
(314178,34909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿El mismo vestido? Ella decide: ... ir a casa y cambiarme.'::text,'debo'::text,'tengo que'::text,'debería'::text,'¿El mismo vestido? Ella decide: debo ir a casa y cambiarme.'::text),
(314177,34909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La même robe ? Elle décide : je ... rentrer me changer.'::text,'dois'::text,'dois'::text,'devrais'::text,'La même robe ? Elle décide : je dois rentrer me changer.'::text),
